(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-2219",module:"changshi",prompt:"划分唯物主义和唯心主义的标准是？",options:["对第二方面的不同回答", "是否承认矛盾", "是否承认发展", "对哲学基本问题第一方面的不同回答"],answer:3,explanation:"凡认为存在决定思维的属于唯物主义，反之属于唯心主义。"},{id:"cs-2220",module:"changshi",prompt:"划分可知论和不可知论的标准是？",options:["对哲学基本问题第二方面的不同回答", "是否承认发展", "对第一方面的不同回答", "是否承认矛盾"],answer:0,explanation:"凡认为思维能够认识存在的属于可知论，反之属于不可知论。"},{id:"cs-2221",module:"changshi",prompt:"唯物主义的三种历史形态不包括？",options:["辩证唯物主义", "主观唯物主义", "近代形而上学唯物主义", "古代朴素唯物主义"],answer:1,explanation:"唯物主义三种形态为古代朴素、近代形而上学、辩证唯物主义和历史唯物主义。"},{id:"cs-2222",module:"changshi",prompt:"“气者，理之依也”属于？",options:["辩证唯物主义", "客观唯心主义", "主观唯心主义", "古代朴素唯物主义"],answer:3,explanation:"王夫之的“气者，理之依也”把世界的本原归结为“气”，属于古代朴素唯物主义。"},{id:"cs-2223",module:"changshi",prompt:"“存在就是被感知”属于？",options:["主观唯心主义", "客观唯心主义", "古代朴素唯物主义", "辩证唯物主义"],answer:0,explanation:"贝克莱把世界的本原归结为个人的感觉，属于主观唯心主义。"},{id:"cs-2224",module:"changshi",prompt:"“上帝创世说”属于？",options:["客观唯心主义", "主观唯心主义", "古代朴素唯物主义", "辩证唯物主义"],answer:0,explanation:"把“上帝”作为世界的本原，属于客观唯心主义。"},{id:"cs-2225",module:"changshi",prompt:"辩证法的两个总特征是？",options:["联系的观点和发展的观点", "对立统一", "质量互变", "否定之否定"],answer:0,explanation:"联系和发展是唯物辩证法的总特征。"},{id:"cs-2226",module:"changshi",prompt:"矛盾普遍性和特殊性的关系是？",options:["整体和部分的关系", "绝对和相对的关系", "内容和形式的关系", "共性和个性的关系"],answer:3,explanation:"普遍性寓于特殊性之中，特殊性包含普遍性。"},{id:"cs-2227",module:"changshi",prompt:"主要矛盾和次要矛盾的关系是？",options:["次要矛盾决定事物发展的基本方向", "二者没有关系", "二者可以相互替代", "主要矛盾决定事物发展的基本方向"],answer:3,explanation:"主要矛盾在事物发展中处于支配地位，起决定作用。"},{id:"cs-2228",module:"changshi",prompt:"矛盾的主要方面和次要方面的关系是？",options:["二者没有关系", "矛盾的主要方面决定事物的性质", "二者可以相互替代", "次要方面决定事物的性质"],answer:1,explanation:"矛盾的主要方面决定事物的性质。"},{id:"cs-2229",module:"changshi",prompt:"质量互变规律揭示了？",options:["事物发展的形式和状态", "事物发展的本质", "事物发展的动力", "事物发展的方向和道路"],answer:0,explanation:"质量互变规律揭示了事物发展的形式和状态。"},{id:"cs-2230",module:"changshi",prompt:"否定之否定规律揭示了？",options:["事物发展的本质", "事物发展的动力", "事物发展的形式和状态", "事物发展的方向和道路（前进性与曲折性的统一）"],answer:3,explanation:"否定之否定规律揭示了事物发展的方向和道路。"},{id:"cs-2231",module:"changshi",prompt:"对立统一规律揭示了？",options:["事物发展的方向和道路", "事物发展的本质", "事物发展的形式和状态", "事物发展的动力和源泉"],answer:3,explanation:"对立统一规律揭示了事物发展的动力和源泉。"},{id:"cs-2232",module:"changshi",prompt:"“量变是质变的必要准备，质变是量变的必然结果”说明？",options:["量变和质变没有关系", "量变可以脱离质变", "质变可以脱离量变", "事物的发展是量变和质变的统一"],answer:3,explanation:"量变和质变相互依存、相互转化。"},{id:"cs-2233",module:"changshi",prompt:"“实践是检验真理的唯一标准”说明？",options:["实践具有主观性", "实践具有客观性", "实践具有直接现实性", "实践具有社会性"],answer:2,explanation:"实践的直接现实性使它成为检验真理的唯一标准。"},{id:"cs-2234",module:"changshi",prompt:"认识的两次飞跃是指？",options:["从理性认识到感性认识，从感性认识到实践", "从实践到认识，从认识到实践", "从感性认识到实践，从实践到理性认识", "从感性认识到理性认识，从理性认识到实践"],answer:3,explanation:"第一次飞跃是从感性认识到理性认识，第二次飞跃是从理性认识到实践。"},{id:"cs-2235",module:"changshi",prompt:"社会存在和社会意识的关系是？",options:["社会意识决定社会存在", "二者没有关系", "社会存在决定社会意识，社会意识具有相对独立性", "二者可以相互替代"],answer:2,explanation:"社会存在决定社会意识，社会意识对社会存在具有反作用。"},{id:"cs-2236",module:"changshi",prompt:"生产力和生产关系的关系是？",options:["生产关系决定生产力", "二者没有关系", "二者可以相互替代", "生产力决定生产关系，生产关系对生产力具有反作用"],answer:3,explanation:"生产力决定生产关系，生产关系对生产力具有反作用。"},{id:"cs-2237",module:"changshi",prompt:"经济基础和上层建筑的关系是？",options:["二者没有关系", "上层建筑决定经济基础", "二者可以相互替代", "经济基础决定上层建筑，上层建筑对经济基础具有反作用"],answer:3,explanation:"经济基础决定上层建筑，上层建筑对经济基础具有反作用。"},{id:"cs-2238",module:"changshi",prompt:"人民群众是历史的创造者，这是因为？",options:["人民群众是历史的旁观者", "人民群众是社会物质财富和精神财富的创造者，是社会变革的决定力量", "人民群众是历史的阻力", "人民群众是历史的被动因素"],answer:1,explanation:"人民群众是历史的创造者，是社会变革的决定力量。"},{id:"cs-2239",module:"changshi",prompt:"“人的本质是一切社会关系的总和”出自？",options:["马克思", "毛泽东", "列宁", "恩格斯"],answer:0,explanation:"马克思在《关于费尔巴哈的提纲》中提出。"},{id:"cs-2240",module:"changshi",prompt:"“实事求是”中的“是”指的是？",options:["实践经验", "主观认识", "客观事物", "客观事物的内部联系，即规律性"],answer:3,explanation:"“实事求是”中的“是”指客观事物的内部联系，即规律性。"},{id:"cs-2241",module:"changshi",prompt:"“解放思想”与“实事求是”的关系是？",options:["二者可以相互替代", "二者相互矛盾", "二者没有关系", "解放思想是实事求是的前提，实事求是是解放思想的目的"],answer:3,explanation:"解放思想和实事求是是辩证统一的。"},{id:"cs-2242",module:"changshi",prompt:"“一切从实际出发”的哲学依据是？",options:["二者可以相互替代", "意识决定物质", "二者没有关系", "物质决定意识"],answer:3,explanation:"一切从实际出发的哲学依据是物质决定意识。"},{id:"cs-2243",module:"changshi",prompt:"“具体问题具体分析”的哲学依据是？",options:["矛盾的普遍性", "矛盾的特殊性", "矛盾的斗争性", "矛盾的同一性"],answer:1,explanation:"具体问题具体分析的哲学依据是矛盾的特殊性。"},{id:"cs-2244",module:"changshi",prompt:"“两点论”和“重点论”的关系是？",options:["二者可以相互替代", "二者没有关系", "两点论和重点论是辩证统一的", "二者相互矛盾"],answer:2,explanation:"两点论和重点论是辩证统一的，即既要全面又要抓住重点。"},{id:"cs-2245",module:"changshi",prompt:"“一分为二”的哲学依据是？",options:["矛盾的斗争性", "矛盾的同一性", "矛盾的普遍性", "矛盾的特殊性"],answer:2,explanation:"“一分为二”的哲学依据是矛盾的普遍性。"},{id:"cs-2246",module:"changshi",prompt:"“合二为一”的哲学依据是？",options:["矛盾的特殊性", "矛盾的同一性", "矛盾的斗争性", "矛盾的普遍性"],answer:1,explanation:"“合二为一”的哲学依据是矛盾的同一性。"},{id:"cs-2247",module:"changshi",prompt:"“内因”和“外因”的关系是？",options:["内因是事物发展的根据，外因是事物发展的条件，外因通过内因起作用", "内因和外因可以相互替代", "外因是事物发展的根据", "内因和外因没有关系"],answer:0,explanation:"内因是事物发展的根据，外因是事物发展的条件。"},{id:"cs-2248",module:"changshi",prompt:"“联系”的观点是指？",options:["事物之间没有关系", "事物之间相互对立", "事物之间以及事物内部各要素之间相互影响、相互制约、相互作用", "事物之间相互独立"],answer:2,explanation:"联系的观点是唯物辩证法的总特征之一。"},{id:"cs-2249",module:"changshi",prompt:"“发展”的观点是指？",options:["事物的循环运动", "事物由低级到高级、由简单到复杂的前进上升运动", "事物的静止状态", "事物的倒退运动"],answer:1,explanation:"发展的观点是唯物辩证法的总特征之一。"},{id:"cs-2250",module:"changshi",prompt:"“系统”的观点是指？",options:["事物是静止的", "事物是孤立的", "事物是片面的", "事物是由相互联系、相互作用的要素构成的有机整体"],answer:3,explanation:"系统的观点要求我们用整体和联系的观点看问题。"},{id:"cs-2251",module:"changshi",prompt:"“过程”的观点是指？",options:["事物是孤立的", "事物是静止的", "事物是不断发展变化的", "事物是永恒的"],answer:2,explanation:"过程的观点要求我们用发展的观点看问题。"},{id:"cs-2252",module:"changshi",prompt:"“创新”的哲学依据是？",options:["发展的观点", "孤立的观点", "静止的观点", "片面的观点"],answer:0,explanation:"创新的哲学依据是发展的观点。"},{id:"cs-2253",module:"changshi",prompt:"“改革”的哲学依据是？",options:["思维规律", "社会基本矛盾运动的规律", "自然规律", "经济规律"],answer:1,explanation:"改革的哲学依据是社会基本矛盾运动的规律。"},{id:"cs-2254",module:"changshi",prompt:"“开放”的哲学依据是？",options:["片面的观点", "孤立的观点", "静止的观点", "普遍联系的观点"],answer:3,explanation:"开放的哲学依据是普遍联系的观点。"},{id:"cs-2255",module:"changshi",prompt:"“协调”的哲学依据是？",options:["片面的观点", "孤立的观点", "系统优化的方法", "静止的观点"],answer:2,explanation:"协调的哲学依据是系统优化的方法。"},{id:"cs-2256",module:"changshi",prompt:"“绿色”的哲学依据是？",options:["自然中心主义的观点", "人与自然和谐共生的观点", "人定胜天的观点", "人与自然对立的观点"],answer:1,explanation:"绿色的哲学依据是人与自然和谐共生的观点。"},{id:"cs-2257",module:"changshi",prompt:"“共享”的哲学依据是？",options:["人民群众是历史创造者的观点", "形而上学史观", "唯心史观", "英雄史观"],answer:0,explanation:"共享的哲学依据是人民群众是历史创造者的观点。"},{id:"cs-2258",module:"changshi",prompt:"“四个全面”战略布局是指？",options:["全面小康、全面改革、全面法治、全面治党", "全面创新、全面协调、全面绿色、全面开放", "全面建设社会主义现代化国家、全面深化改革、全面依法治国、全面从严治党", "全面富裕、全面文明、全面和谐、全面美丽"],answer:2,explanation:"“四个全面”战略布局是新时代党的战略布局。"},{id:"cs-2259",module:"changshi",prompt:"“两个一百年”奋斗目标是指？",options:["建党一百年时实现小康，建国一百年时实现温饱", "建党一百年时实现温饱，建国一百年时实现小康", "建党一百年时实现现代化，建国一百年时实现小康", "建党一百年时全面建成小康社会，建国一百年时建成社会主义现代化强国"],answer:3,explanation:"“两个一百年”奋斗目标是新时代中国特色社会主义的战略安排。"},{id:"cs-2260",module:"changshi",prompt:"“新发展理念”是指？",options:["创新、协调、绿色、开放、共享", "创新、协调、绿色、共享、发展", "创新、协调、开放、共享、发展", "创新、协调、绿色、开放、发展"],answer:0,explanation:"“新发展理念”是新时代中国特色社会主义的基本方略之一。"},{id:"cs-2261",module:"changshi",prompt:"“社会主义核心价值观”的国家层面是？",options:["爱国、敬业、诚信、友善", "创新、协调、绿色、开放", "富强、民主、文明、和谐", "自由、平等、公正、法治"],answer:2,explanation:"社会主义核心价值观的国家层面是富强、民主、文明、和谐。"},{id:"cs-2262",module:"changshi",prompt:"“社会主义核心价值观”的社会层面是？",options:["爱国、敬业、诚信、友善", "自由、平等、公正、法治", "创新、协调、绿色、开放", "富强、民主、文明、和谐"],answer:1,explanation:"社会主义核心价值观的社会层面是自由、平等、公正、法治。"},{id:"cs-2263",module:"changshi",prompt:"“社会主义核心价值观”的个人层面是？",options:["自由、平等、公正、法治", "富强、民主、文明、和谐", "创新、协调、绿色、开放", "爱国、敬业、诚信、友善"],answer:3,explanation:"社会主义核心价值观的个人层面是爱国、敬业、诚信、友善。"},{id:"cs-2264",module:"changshi",prompt:"“四个自信”中最基础的是？",options:["文化自信", "道路自信", "制度自信", "理论自信"],answer:0,explanation:"文化自信是更基础、更广泛、更深厚的自信。"},{id:"cs-2265",module:"changshi",prompt:"“四个全面”战略布局中居于保障地位的是？",options:["全面建设社会主义现代化国家", "全面从严治党", "全面深化改革", "全面依法治国"],answer:3,explanation:"全面依法治国是“四个全面”战略布局中居于保障地位的法治保障。"},{id:"cs-2266",module:"changshi",prompt:"“四个全面”战略布局中居于动力地位的是？",options:["全面从严治党", "全面依法治国", "全面建设社会主义现代化国家", "全面深化改革"],answer:3,explanation:"全面深化改革是“四个全面”战略布局中居于动力地位的改革动力。"},{id:"cs-2267",module:"changshi",prompt:"“四个全面”战略布局中居于根本保证地位的是？",options:["全面从严治党", "全面深化改革", "全面建设社会主义现代化国家", "全面依法治国"],answer:0,explanation:"全面从严治党是“四个全面”战略布局中居于根本保证地位的政治保证。"},{id:"cs-2268",module:"changshi",prompt:"“新发展理念”中居于首位的是？",options:["协调", "开放", "创新", "绿色"],answer:2,explanation:"创新是引领发展的第一动力，在新发展理念中居于首位。"},{id:"cs-2269",module:"changshi",prompt:"“新发展理念”中居于基础地位的是？",options:["创新", "开放", "绿色", "协调"],answer:3,explanation:"协调是持续健康发展的内在要求，在新发展理念中居于基础地位。"},{id:"cs-2270",module:"changshi",prompt:"“新发展理念”中居于保障地位的是？",options:["开放", "协调", "创新", "绿色"],answer:3,explanation:"绿色是永续发展的必要条件，在新发展理念中居于保障地位。"},{id:"cs-2271",module:"changshi",prompt:"“新发展理念”中居于路径地位的是？",options:["绿色", "创新", "协调", "开放"],answer:3,explanation:"开放是国家繁荣发展的必由之路，在新发展理念中居于路径地位。"},{id:"cs-2272",module:"changshi",prompt:"“新发展理念”中居于目的地位的是？",options:["协调", "共享", "创新", "绿色"],answer:1,explanation:"共享是中国特色社会主义的本质要求，在新发展理念中居于目的地位。"},{id:"cs-2273",module:"changshi",prompt:"“四个自信”中居于根本地位的是？",options:["道路自信", "文化自信", "理论自信", "制度自信"],answer:0,explanation:"道路自信是“四个自信”中居于根本地位的自信。"},{id:"cs-2274",module:"changshi",prompt:"“四个自信”中居于指导地位的是？",options:["道路自信", "制度自信", "文化自信", "理论自信"],answer:3,explanation:"理论自信是“四个自信”中居于指导地位的自信。"},{id:"cs-2275",module:"changshi",prompt:"“四个自信”中居于保障地位的是？",options:["理论自信", "道路自信", "文化自信", "制度自信"],answer:3,explanation:"制度自信是“四个自信”中居于保障地位的自信。"},{id:"cs-2276",module:"changshi",prompt:"“四个自信”中居于精神地位的是？",options:["制度自信", "文化自信", "理论自信", "道路自信"],answer:1,explanation:"文化自信是“四个自信”中居于精神地位的自信。"},{id:"cs-2277",module:"changshi",prompt:"“四个意识”中居于首位的是？",options:["核心意识", "大局意识", "政治意识", "看齐意识"],answer:2,explanation:"政治意识是“四个意识”中居于首位的意识。"},{id:"cs-2278",module:"changshi",prompt:"“四个意识”中居于基础地位的是？",options:["大局意识", "核心意识", "看齐意识", "政治意识"],answer:0,explanation:"大局意识是“四个意识”中居于基础地位的意识。"},{id:"cs-2279",module:"changshi",prompt:"“四个意识”中居于核心地位的是？",options:["政治意识", "核心意识", "看齐意识", "大局意识"],answer:1,explanation:"核心意识是“四个意识”中居于核心地位的意识。"},{id:"cs-2280",module:"changshi",prompt:"“四个意识”中居于保障地位的是？",options:["大局意识", "政治意识", "看齐意识", "核心意识"],answer:2,explanation:"看齐意识是“四个意识”中居于保障地位的意识。"},{id:"cs-2281",module:"changshi",prompt:"“四个伟大”中居于首位的是？",options:["伟大梦想", "伟大斗争", "伟大事业", "伟大工程"],answer:1,explanation:"伟大斗争是“四个伟大”中居于首位的伟大。"},{id:"cs-2282",module:"changshi",prompt:"“四个伟大”中居于保障地位的是？",options:["伟大事业", "伟大梦想", "伟大斗争", "伟大工程"],answer:3,explanation:"伟大工程是“四个伟大”中居于保障地位的伟大。"},{id:"cs-2283",module:"changshi",prompt:"“四个伟大”中居于主体地位的是？",options:["伟大梦想", "伟大事业", "伟大工程", "伟大斗争"],answer:1,explanation:"伟大事业是“四个伟大”中居于主体地位的伟大。"},{id:"cs-2284",module:"changshi",prompt:"“四个伟大”中居于目标地位的是？",options:["伟大梦想", "伟大工程", "伟大事业", "伟大斗争"],answer:0,explanation:"伟大梦想是“四个伟大”中居于目标地位的伟大。"},{id:"cs-2285",module:"changshi",prompt:"“两个一百年”奋斗目标中居于首位的是？",options:["二者没有先后", "建国一百年时建成社会主义现代化强国", "建党一百年时全面建成小康社会", "二者可以同时实现"],answer:2,explanation:"建党一百年时全面建成小康社会是“两个一百年”奋斗目标中居于首位的目标。"},{id:"cs-2286",module:"changshi",prompt:"“两个一百年”奋斗目标中居于目标地位的是？",options:["建国一百年时建成社会主义现代化强国", "建党一百年时全面建成小康社会", "二者没有先后", "二者可以同时实现"],answer:0,explanation:"建国一百年时建成社会主义现代化强国是“两个一百年”奋斗目标中居于目标地位的目标。"},{id:"cs-2287",module:"changshi",prompt:"“中国梦”的本质中居于首位的是？",options:["国家富强", "民族振兴", "人民幸福", "三者没有先后"],answer:0,explanation:"国家富强是“中国梦”本质中居于首位的内容。"},{id:"cs-2288",module:"changshi",prompt:"“中国梦”的本质中居于基础地位的是？",options:["民族振兴", "三者没有先后", "人民幸福", "国家富强"],answer:0,explanation:"民族振兴是“中国梦”本质中居于基础地位的内容。"},{id:"cs-2289",module:"changshi",prompt:"“中国梦”的本质中居于目的地位的是？",options:["民族振兴", "三者没有先后", "国家富强", "人民幸福"],answer:3,explanation:"人民幸福是“中国梦”本质中居于目的地位的内容。"},{id:"cs-2290",module:"changshi",prompt:"“五位一体”总体布局中居于首位的是？",options:["文化建设", "社会建设", "经济建设", "政治建设"],answer:2,explanation:"经济建设是“五位一体”总体布局中居于首位的建设。"},{id:"cs-2291",module:"changshi",prompt:"“五位一体”总体布局中居于保障地位的是？",options:["文化建设", "政治建设", "经济建设", "社会建设"],answer:1,explanation:"政治建设是“五位一体”总体布局中居于保障地位的建设。"},{id:"cs-2292",module:"changshi",prompt:"“五位一体”总体布局中居于灵魂地位的是？",options:["经济建设", "文化建设", "政治建设", "社会建设"],answer:1,explanation:"文化建设是“五位一体”总体布局中居于灵魂地位的建设。"},{id:"cs-2293",module:"changshi",prompt:"“五位一体”总体布局中居于基础地位的是？",options:["社会建设", "文化建设", "政治建设", "经济建设"],answer:0,explanation:"社会建设是“五位一体”总体布局中居于基础地位的建设。"},{id:"cs-2294",module:"changshi",prompt:"“五位一体”总体布局中居于条件地位的是？",options:["经济建设", "生态文明建设", "文化建设", "政治建设"],answer:1,explanation:"生态文明建设是“五位一体”总体布局中居于条件地位的建设。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-2295",module:"changshi",prompt:"现行宪法自颁布以来共经历了几次修正（截至2018年）？",options:["3次", "4次", "5次", "6次"],answer:2,explanation:"1982年宪法历经1988、1993、1999、2004、2018年五次修正。"},{id:"cs-2296",module:"changshi",prompt:"宪法修正案由谁公布？",options:["全国人大主席团", "全国人大常委会", "国务院", "国家主席"],answer:3,explanation:"宪法修正案由全国人大主席团公布，实践中由全国人大公告公布施行。"},{id:"cs-2297",module:"changshi",prompt:"我国宪法规定，国家的一切权力属于谁？",options:["公民", "人民", "全国人大", "中国共产党"],answer:1,explanation:"宪法第二条：中华人民共和国的一切权力属于人民。"},{id:"cs-2298",module:"changshi",prompt:"人民行使国家权力的机关是？",options:["中国共产党", "全国人大和地方各级人大", "国务院和地方各级政府", "政协"],answer:1,explanation:"宪法第二条：人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。"},{id:"cs-2299",module:"changshi",prompt:"我国的国家性质（国体）是？",options:["人民民主专政", "无产阶级专政", "工农民主专政", "各革命阶级联合专政"],answer:0,explanation:"宪法第一条：中华人民共和国是工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家。"},{id:"cs-2300",module:"changshi",prompt:"我国的爱国统一战线组织是？",options:["人民代表大会", "中国人民政治协商会议", "工会", "共青团"],answer:1,explanation:"中国人民政治协商会议是有广泛代表性的统一战线组织。"},{id:"cs-2301",module:"changshi",prompt:"民族区域自治制度是？",options:["根本政治制度", "基本政治制度", "基本经济制度", "根本制度"],answer:1,explanation:"民族区域自治制度是我国的基本政治制度之一。"},{id:"cs-2302",module:"changshi",prompt:"基层群众自治制度中，城市居民委员会的任期是？",options:["3年", "4年", "5年", "2年"],answer:2,explanation:"根据《城市居民委员会组织法》，居委会每届任期5年（2018年修法后与村委会一致）。"},{id:"cs-2303",module:"changshi",prompt:"村民委员会由村民直接选举产生，每届任期？",options:["3年", "5年", "4年", "2年"],answer:1,explanation:"《村民委员会组织法》规定村委会每届任期5年，可连选连任。"},{id:"cs-2304",module:"changshi",prompt:"我国宪法规定的公民基本权利中，首要的权利是？",options:["平等权", "选举权", "人身自由", "言论自由"],answer:0,explanation:"平等权是公民的基本权利，也是其他权利得以实现的基础。"},{id:"cs-2305",module:"changshi",prompt:"我国公民的选举权始于？",options:["年满16周岁", "年满18周岁", "年满20周岁", "年满22周岁"],answer:1,explanation:"年满18周岁的公民享有选举权和被选举权（依法被剥夺者除外）。"},{id:"cs-2306",module:"changshi",prompt:"下列哪项不属于公民的政治权利和自由？",options:["选举权", "被选举权", "言论自由", "宗教信仰自由"],answer:3,explanation:"宗教信仰自由属于公民的基本权利，但不属于政治权利和自由。"},{id:"cs-2307",module:"changshi",prompt:"我国宪法规定，公民的通信自由和通信秘密受法律保护，除因国家安全或追查刑事犯罪的需要，由谁依照法律程序检查通信外，任何组织或个人不得侵犯？",options:["公安机关或检察机关", "法院", "单位领导", "居委会"],answer:0,explanation:"宪法第四十条：由公安机关或者检察机关依照法律规定的程序对通信进行检查。"},{id:"cs-2308",module:"changshi",prompt:"我国宪法规定，公民对于任何国家机关和国家工作人员有提出批评和建议的权利，这属于？",options:["申诉权", "控告权", "批评建议权", "检举权"],answer:2,explanation:"宪法第四十一条规定了公民的批评建议权、申诉控告检举权和国家赔偿请求权。"},{id:"cs-2309",module:"changshi",prompt:"国家赔偿请求权的依据是？",options:["宪法第四十一条", "宪法第三十三条", "宪法第三十五条", "宪法第三十八条"],answer:0,explanation:"宪法第四十一条规定，由于国家机关和国家工作人员侵犯公民权利而受到损失的人，有依照法律规定取得赔偿的权利。"},{id:"cs-2310",module:"changshi",prompt:"我国宪法规定，公民的人格尊严不受侵犯，禁止用任何方法对公民进行？",options:["侮辱、诽谤和诬告陷害", "搜查", "拘留", "罚款"],answer:0,explanation:"宪法第三十八条：禁止用任何方法对公民进行侮辱、诽谤和诬告陷害。"},{id:"cs-2311",module:"changshi",prompt:"我国宪法规定，国家为了公共利益的需要，可以依照法律规定对公民的私有财产实行？",options:["征收或者征用并给予补偿", "无偿征收", "直接没收", "冻结"],answer:0,explanation:"宪法第十三条：国家为了公共利益的需要，可以依照法律规定对土地实行征收或者征用并给予补偿；对公民私有财产同样征收征用并补偿。"},{id:"cs-2312",module:"changshi",prompt:"我国宪法规定，社会主义的公共财产神圣不可侵犯，其中全民所有制即？",options:["国有经济", "集体经济", "私营经济", "个体经济"],answer:0,explanation:"宪法第七条：国有经济，即社会主义全民所有制经济，是国民经济中的主导力量。"},{id:"cs-2313",module:"changshi",prompt:"我国宪法规定，在法律规定范围内的个体经济、私营经济等非公有制经济是？",options:["社会主义公有制经济的补充", "社会主义市场经济的重要组成部分", "国民经济的主导力量", "社会主义经济制度的基础"],answer:1,explanation:"宪法第十一条：非公有制经济是社会主义市场经济的重要组成部分。"},{id:"cs-2314",module:"changshi",prompt:"我国宪法规定，农村集体经济组织实行？",options:["家庭承包经营为基础、统分结合的双层经营体制", "集体统一经营", "个体经营", "公司化经营"],answer:0,explanation:"宪法第八条规定了农村集体经济组织的双层经营体制。"},{id:"cs-2315",module:"changshi",prompt:"农村和城市郊区的土地，除法律规定属于国家所有的以外，属于？",options:["国家所有", "集体所有", "个人所有", "使用者所有"],answer:1,explanation:"宪法第十条：农村和城市郊区的土地，除由法律规定属于国家所有的以外，属于集体所有。"},{id:"cs-2316",module:"changshi",prompt:"宅基地、自留地、自留山属于？",options:["国家所有", "集体所有", "个人所有", "共有"],answer:1,explanation:"宪法第十条：宅基地和自留地、自留山，也属于集体所有。"},{id:"cs-2317",module:"changshi",prompt:"我国的国家机构实行什么原则？",options:["三权分立", "民主集中制", "议行合一", "联邦制"],answer:1,explanation:"宪法第三条：中华人民共和国的国家机构实行民主集中制的原则。"},{id:"cs-2318",module:"changshi",prompt:"全国人大会议每年举行一次，由谁召集？",options:["全国人大常委会", "国家主席", "国务院", "全国人大主席团"],answer:0,explanation:"全国人大会议每年由全国人大常委会召集。"},{id:"cs-2319",module:"changshi",prompt:"全国人大举行会议时，选举谁主持？",options:["全国人大常委会委员长", "主席团", "国家主席", "国务院总理"],answer:1,explanation:"全国人大每次会议举行预备会议，选举本次会议的主席团，由主席团主持本次会议。"},{id:"cs-2320",module:"changshi",prompt:"有权解释宪法的机关是？",options:["全国人大", "全国人大常委会", "最高人民法院", "国务院"],answer:1,explanation:"宪法第六十七条：全国人大常委会负责解释宪法。"},{id:"cs-2321",module:"changshi",prompt:"有权监督宪法实施的机关是？",options:["全国人大和全国人大常委会", "最高人民法院", "国务院", "中央军委"],answer:0,explanation:"宪法第六十二条、第六十七条：全国人大和全国人大常委会监督宪法的实施。"},{id:"cs-2322",module:"changshi",prompt:"全国人大常委会的组成人员不得担任？",options:["国家行政机关、监察机关、审判机关、检察机关的职务", "党的职务", "政协职务", "军队职务"],answer:0,explanation:"宪法第六十五条：全国人大常委会的组成人员不得担任国家行政机关、监察机关、审判机关和检察机关的职务。"},{id:"cs-2323",module:"changshi",prompt:"全国人大专门委员会中，负责审议议案中法律问题的是？",options:["民族委员会", "宪法和法律委员会", "财政经济委员会", "教育科学文化卫生委员会"],answer:1,explanation:"宪法和法律委员会统一审议向全国人大或常委会提出的法律案。"},{id:"cs-2324",module:"changshi",prompt:"有权决定战争与和平问题的机关是？",options:["全国人大", "全国人大常委会", "国家主席", "中央军委"],answer:0,explanation:"宪法第六十二条：全国人大决定战争和和平的问题。"},{id:"cs-2325",module:"changshi",prompt:"全国人大闭会期间，有权决定战争状态的宣布的是？",options:["全国人大常委会", "国家主席", "中央军委", "国务院"],answer:0,explanation:"全国人大闭会期间，全国人大常委会决定战争状态的宣布。"},{id:"cs-2326",module:"changshi",prompt:"根据宪法，宣布进入紧急状态、宣布战争状态的职权由谁行使？",options:["国家主席", "全国人大常委会", "国务院", "中央军委"],answer:0,explanation:"宪法第八十条：国家主席根据全国人大及其常委会的决定，宣布进入紧急状态、宣布战争状态等。"},{id:"cs-2327",module:"changshi",prompt:"国务院实行什么负责制？",options:["集体负责制", "总理负责制", "首长负责制与集体负责制结合", "委员制"],answer:1,explanation:"宪法第八十六条：国务院实行总理负责制；各部、各委员会实行部长、主任负责制。"},{id:"cs-2328",module:"changshi",prompt:"国务院总理由谁提名？",options:["全国人大主席团", "国家主席", "全国人大常委会", "中共中央"],answer:1,explanation:"宪法第六十二条：全国人大根据中华人民共和国主席的提名，决定国务院总理的人选。"},{id:"cs-2329",module:"changshi",prompt:"中央军事委员会实行什么负责制？",options:["集体负责制", "主席负责制", "委员制", "合议制"],answer:1,explanation:"宪法第九十三条：中央军委实行主席负责制。"},{id:"cs-2330",module:"changshi",prompt:"中央军委主席由谁产生，对谁负责？",options:["全国人大选举，对全国人大及其常委会负责", "国家主席任命", "国务院任命", "党的代表大会选举"],answer:0,explanation:"中央军委主席由全国人大选举产生，对全国人大及其常委会负责。"},{id:"cs-2331",module:"changshi",prompt:"地方各级人大每届任期？",options:["3年", "4年", "5年", "2年"],answer:2,explanation:"地方各级人大每届任期5年（2004年修法后统一为5年）。"},{id:"cs-2332",module:"changshi",prompt:"地方各级人民政府是？",options:["地方国家权力机关", "地方各级国家权力机关的执行机关，是地方各级国家行政机关", "地方司法机关", "地方党组织"],answer:1,explanation:"宪法第一百零五条：地方各级人民政府是地方各级国家权力机关的执行机关，是地方各级国家行政机关。"},{id:"cs-2333",module:"changshi",prompt:"我国宪法规定，人民法院依照法律规定独立行使审判权，不受谁干涉？",options:["行政机关、社会团体和个人的干涉", "党的领导", "人大的监督", "检察院的监督"],answer:0,explanation:"宪法第一百三十一条：人民法院依照法律规定独立行使审判权，不受行政机关、社会团体和个人的干涉。"},{id:"cs-2334",module:"changshi",prompt:"人民检察院依照法律规定独立行使检察权，不受谁干涉？",options:["行政机关、社会团体和个人的干涉", "党的领导", "人大的监督", "法院的监督"],answer:0,explanation:"宪法第一百三十六条：人民检察院依照法律规定独立行使检察权，不受行政机关、社会团体和个人的干涉。"},{id:"cs-2335",module:"changshi",prompt:"各级监察委员会是国家的？",options:["行政机关", "监察机关", "审判机关", "法律监督机关"],answer:1,explanation:"宪法第一百二十三条：中华人民共和国各级监察委员会是国家的监察机关。"},{id:"cs-2336",module:"changshi",prompt:"国家监察委员会主任由谁选举产生？",options:["全国人大", "全国人大常委会", "国家主席", "国务院"],answer:0,explanation:"国家监察委员会主任由全国人大选举产生。"},{id:"cs-2337",module:"changshi",prompt:"我国宪法规定，婚姻、家庭、母亲和儿童受？",options:["国家保护", "社会保护", "法律保护", "家庭保护"],answer:0,explanation:"宪法第四十九条：婚姻、家庭、母亲和儿童受国家的保护。"},{id:"cs-2338",module:"changshi",prompt:"我国宪法规定，国家推行计划生育，使人口的增长同经济和社会发展计划相适应，该条款属于？",options:["公民的基本权利", "国家的基本政策", "公民的基本义务", "国家机构的规定"],answer:1,explanation:"计划生育条款属于国家基本政策（基本国策）的规定。"},{id:"cs-2339",module:"changshi",prompt:"我国宪法规定，公民有依照法律纳税的义务，这属于？",options:["公民的基本权利", "公民的基本义务", "国家机关的职权", "国家的基本政策"],answer:1,explanation:"宪法第五十六条：中华人民共和国公民有依照法律纳税的义务。"},{id:"cs-2340",module:"changshi",prompt:"下列哪项属于公民的基本义务？",options:["劳动权", "受教育权", "维护国家安全、荣誉和利益的义务", "宗教信仰自由"],answer:2,explanation:"维护国家安全、荣誉和利益是公民的基本义务；劳动和受教育既是权利也是义务。"},{id:"cs-2341",module:"changshi",prompt:"宪法宣誓制度适用于？",options:["各级人大及其常委会选举或决定任命的国家工作人员", "所有公务员", "所有党员", "所有法官检察官"],answer:0,explanation:"根据《全国人大常委会关于实行宪法宣誓制度的决定》，各级人大及县级以上人大常委会选举或决定任命的国家工作人员就职时应当进行宪法宣誓。"},{id:"cs-2342",module:"changshi",prompt:"我国宪法序言规定，国家的根本任务是？",options:["沿着中国特色社会主义道路，集中力量进行社会主义现代化建设", "发展市场经济", "实现共同富裕", "建设法治国家"],answer:0,explanation:"宪法序言规定了国家的根本任务。"},{id:"cs-2343",module:"changshi",prompt:"我国宪法规定，中华人民共和国是统一的多民族国家，采取的国家结构形式是？",options:["联邦制", "单一制", "邦联制", "复合制"],answer:1,explanation:"我国采取单一制的国家结构形式，同时实行民族区域自治。"},{id:"cs-2344",module:"changshi",prompt:"法的本质属性不包括？",options:["阶级性", "国家意志性", "规范性", "随意性"],answer:3,explanation:"法具有阶级性、国家意志性、规范性、强制性等属性，不具有随意性。"},{id:"cs-2345",module:"changshi",prompt:"法的社会作用主要体现为？",options:["维护阶级统治和执行社会公共事务", "指引和评价", "预测和教育", "强制和惩罚"],answer:0,explanation:"法的社会作用包括维护阶级统治和执行社会公共事务两个方面。"},{id:"cs-2346",module:"changshi",prompt:"法的指引作用的对象是？",options:["本人的行为", "他人的行为", "一般人的行为", "违法行为"],answer:0,explanation:"指引作用的对象是每个人自己的行为。"},{id:"cs-2347",module:"changshi",prompt:"法的评价作用的对象是？",options:["他人的行为", "本人的行为", "一般人的行为", "违法行为"],answer:0,explanation:"评价作用的对象是他人的行为，判断其是否合法有效。"},{id:"cs-2348",module:"changshi",prompt:"法的预测作用的对象是？",options:["人们相互之间的行为", "本人的行为", "他人的行为", "违法行为"],answer:0,explanation:"预测作用的对象是人们相互之间的行为，可以预先估计行为的后果。"},{id:"cs-2349",module:"changshi",prompt:"法的教育作用的对象是？",options:["一般人的行为", "本人的行为", "他人的行为", "违法行为"],answer:0,explanation:"教育作用的对象是一般人的行为，通过法的实施对一般人产生影响。"},{id:"cs-2350",module:"changshi",prompt:"法的强制作用的对象是？",options:["违法行为", "合法行为", "一般人的行为", "本人的行为"],answer:0,explanation:"强制作用的对象是违法行为，制裁违法、犯罪行为。"},{id:"cs-2351",module:"changshi",prompt:"法律规则的三要素是？",options:["假定条件、行为模式、法律后果", "假定条件、法律后果、制裁", "行为模式、法律后果、制裁", "假定条件、行为模式、制裁"],answer:0,explanation:"法律规则由假定条件、行为模式和法律后果三要素构成。"},{id:"cs-2352",module:"changshi",prompt:"按照行为模式的不同，法律规则可分为？",options:["授权性规则和义务性规则", "确定性规则和委任性规则", "强行性规则和任意性规则", "调整性规则和构成性规则"],answer:0,explanation:"按行为模式，法律规则分为授权性规则（可为模式）和义务性规则（应为、勿为模式）。"},{id:"cs-2353",module:"changshi",prompt:"按照规则的强制性程度，法律规则可分为？",options:["强行性规则和任意性规则", "授权性规则和义务性规则", "确定性规则和委任性规则", "调整性规则和构成性规则"],answer:0,explanation:"强行性规则不允许个人自主选择，任意性规则允许个人自主选择。"},{id:"cs-2354",module:"changshi",prompt:"法律原则与法律规则的区别不包括？",options:["原则具有宏观指导性，规则具有微观指导性", "原则适用时具有较大裁量空间，规则适用时裁量空间较小", "原则冲突时依强度权衡，规则冲突时依效力等级或位阶解决", "原则没有法律效力"],answer:3,explanation:"法律原则同样具有法律效力，可以作为裁判依据。"},{id:"cs-2355",module:"changshi",prompt:"我国法律渊源中效力最高的是？",options:["宪法", "法律", "行政法规", "地方性法规"],answer:0,explanation:"宪法具有最高法律效力，一切法律、法规不得与宪法相抵触。"},{id:"cs-2356",module:"changshi",prompt:"行政法规的制定机关是？",options:["全国人大", "国务院", "省级人大", "国务院各部委"],answer:1,explanation:"行政法规由国务院制定，效力低于宪法和法律。"},{id:"cs-2357",module:"changshi",prompt:"地方性法规的制定机关是？",options:["国务院", "省级人大及其常委会、设区的市人大及其常委会", "国务院各部委", "最高人民法院"],answer:1,explanation:"地方性法规由省级人大及其常委会和设区的市人大及其常委会制定。"},{id:"cs-2358",module:"changshi",prompt:"部门规章的制定机关是？",options:["国务院", "国务院各部委", "省级政府", "全国人大常委会"],answer:1,explanation:"部门规章由国务院各部委制定，效力低于行政法规。"},{id:"cs-2359",module:"changshi",prompt:"地方政府规章的制定机关是？",options:["国务院", "省级和设区的市级人民政府", "省级人大", "全国人大常委会"],answer:1,explanation:"地方政府规章由省级和设区的市级人民政府制定。"},{id:"cs-2360",module:"changshi",prompt:"法律解释中，具有普遍约束力的解释是？",options:["立法解释、司法解释、行政解释", "学理解释", "任意解释", "文义解释"],answer:0,explanation:"立法解释、司法解释、行政解释属于有权解释，具有普遍约束力。"},{id:"cs-2361",module:"changshi",prompt:"全国人大常委会对法律的解释属于？",options:["立法解释", "司法解释", "行政解释", "学理解释"],answer:0,explanation:"全国人大常委会的法律解释权即立法解释权。"},{id:"cs-2362",module:"changshi",prompt:"最高人民法院对审判中具体应用法律的解释属于？",options:["立法解释", "司法解释", "行政解释", "学理解释"],answer:1,explanation:"最高人民法院的司法解释对审判工作具有普遍约束力。"},{id:"cs-2363",module:"changshi",prompt:"法律关系的三要素是？",options:["主体、客体、内容", "主体、客体、形式", "内容、形式、后果", "主体、客体、后果"],answer:0,explanation:"法律关系由主体、客体和内容（权利义务）三要素构成。"},{id:"cs-2364",module:"changshi",prompt:"下列属于法律事件的是？",options:["签订合同", "地震", "侵权行为", "立遗嘱"],answer:1,explanation:"地震等自然现象不以人的意志为转移，属于法律事件。"},{id:"cs-2365",module:"changshi",prompt:"下列属于法律行为的是？",options:["出生", "死亡", "签订合同", "自然灾害"],answer:2,explanation:"签订合同是以人的意志为转移的法律行为。"},{id:"cs-2366",module:"changshi",prompt:"法律责任的主要类型不包括？",options:["道德责任", "民事责任", "刑事责任", "行政责任"],answer:0,explanation:"法律责任包括民事责任、刑事责任、行政责任、违宪责任；道德责任不属于法律责任。"},{id:"cs-2367",module:"changshi",prompt:"法律制裁的主要类型不包括？",options:["民事制裁", "刑事制裁", "行政制裁", "纪律处分"],answer:3,explanation:"法律制裁包括民事制裁、刑事制裁、行政制裁、违宪制裁；纪律处分不属于法律制裁。"},{id:"cs-2368",module:"changshi",prompt:"法律实施的主要方式包括？",options:["法的遵守、法的执行、法的适用", "立法、执法、司法", "守法、违法、制裁", "立法、守法、普法"],answer:0,explanation:"法律实施包括法的遵守（守法）、法的执行（执法）、法的适用（司法）。"},{id:"cs-2369",module:"changshi",prompt:"法的适用的主体主要是？",options:["国家司法机关", "国家行政机关", "公民", "社会团体"],answer:0,explanation:"法的适用（司法）的主体主要是国家司法机关，即法院和检察院。"},{id:"cs-2370",module:"changshi",prompt:"法的执行的主体主要是？",options:["国家行政机关", "国家司法机关", "公民", "社会团体"],answer:0,explanation:"法的执行（执法）的主体主要是国家行政机关及其公职人员。"},{id:"cs-2371",module:"changshi",prompt:"法律监督的主体不包括？",options:["国家机关", "社会组织", "公民", "外国政府"],answer:3,explanation:"法律监督的主体包括国家机关、社会组织和公民；外国政府不是我国法律监督的主体。"},{id:"cs-2372",module:"changshi",prompt:"法律监督的客体主要是？",options:["国家机关及其工作人员的公务行为", "公民的私人行为", "社会团体的行为", "企业的经营行为"],answer:0,explanation:"法律监督的客体主要是国家机关及其工作人员的公务行为。"},{id:"cs-2373",module:"changshi",prompt:"法治与法制的区别不包括？",options:["法治强调法律至上，法制强调法律制度", "法治是动态过程，法制是静态制度", "法治与民主相连，法制不一定以民主为基础", "法治和法制没有区别"],answer:3,explanation:"法治与法制有本质区别：法治强调法律至上、与民主相连，法制仅指法律制度。"},{id:"cs-2374",module:"changshi",prompt:"依法行政的基本要求不包括？",options:["高效便民", "合法行政", "合理行政", "司法独立"],answer:3,explanation:"依法行政的基本要求包括合法行政、合理行政、程序正当、高效便民、诚实守信、权责统一；司法独立不属于依法行政的要求。"},{id:"cs-2375",module:"changshi",prompt:"法律的效力等级原则是？",options:["上位法优于下位法、特别法优于一般法、新法优于旧法", "下位法优于上位法", "一般法优于特别法", "旧法优于新法"],answer:0,explanation:"法律效力等级遵循上位法优于下位法、特别法优于一般法、新法优于旧法的原则。"},{id:"cs-2376",module:"changshi",prompt:"同一机关制定的法律，新旧规定不一致时？",options:["适用新的规定", "适用旧的规定", "由法院决定", "由国务院决定"],answer:0,explanation:"《立法法》规定，同一机关制定的法律，新的规定与旧的规定不一致的，适用新的规定。"},{id:"cs-2377",module:"changshi",prompt:"同一机关制定的法律，特别规定与一般规定不一致时？",options:["适用特别规定", "适用一般规定", "由法院决定", "由国务院决定"],answer:0,explanation:"《立法法》规定，特别规定与一般规定不一致的，适用特别规定。"},{id:"cs-2378",module:"changshi",prompt:"地方性法规与部门规章之间对同一事项的规定不一致，不能确定如何适用时？",options:["由国务院提出意见，认为应适用地方性法规的适用地方性法规，认为应适用部门规章的提请全国人大常委会裁决", "直接适用地方性法规", "直接适用部门规章", "由法院决定"],answer:0,explanation:"《立法法》规定了地方性法规与部门规章冲突的解决机制。"},{id:"cs-2379",module:"changshi",prompt:"部门规章之间、部门规章与地方政府规章之间对同一事项的规定不一致时？",options:["由国务院裁决", "由全国人大常委会裁决", "由最高人民法院裁决", "由省级政府裁决"],answer:0,explanation:"《立法法》规定，部门规章之间、部门规章与地方政府规章之间不一致的，由国务院裁决。"},{id:"cs-2380",module:"changshi",prompt:"法律与行政法规之间对同一事项的新的一般规定与旧的特别规定不一致，不能确定如何适用时？",options:["由全国人大常委会裁决", "由国务院裁决", "由最高人民法院裁决", "由省级人大裁决"],answer:0,explanation:"《立法法》规定，法律与行政法规之间不一致的，由全国人大常委会裁决。"},{id:"cs-2381",module:"changshi",prompt:"立法程序的最后一步是？",options:["公布法律", "表决法律", "审议法律", "起草法律"],answer:0,explanation:"立法程序包括法律案的提出、审议、表决、公布，公布是最后一步。"},{id:"cs-2382",module:"changshi",prompt:"法律公布后，由谁以什么形式公布？",options:["国家主席签署主席令公布", "全国人大常委会委员长公布", "国务院总理公布", "全国人大主席团公布"],answer:0,explanation:"法律由国家主席签署主席令公布。"},{id:"cs-2383",module:"changshi",prompt:"法律生效的时间一般不包括？",options:["公布之日起立即生效", "公布后经过一定期限生效", "公布后到达一定期限生效", "公布后溯及既往生效"],answer:3,explanation:"法律一般不溯及既往，但有利于当事人的除外。"},{id:"cs-2384",module:"changshi",prompt:"我国法律关于溯及力的一般原则是？",options:["从旧兼从轻", "从新兼从重", "从旧兼从重", "从新兼从轻"],answer:0,explanation:"我国法律一般不溯及既往，但新法不认为是犯罪或处罚较轻的适用新法，即从旧兼从轻原则。"},{id:"cs-2385",module:"changshi",prompt:"法对人的效力，我国采取的原则是？",options:["以属地主义为主，与属人主义、保护主义相结合", "纯属地主义", "纯属人主义", "纯保护主义"],answer:0,explanation:"我国采取以属地主义为主，与属人主义、保护主义相结合的原则。"},{id:"cs-2386",module:"changshi",prompt:"法律的空间效力一般及于？",options:["国家主权管辖的范围", "仅陆地领土", "仅领海", "仅领空"],answer:0,explanation:"法律的空间效力一般及于国家主权管辖的全部范围，包括领陆、领水、领空及底土。"},{id:"cs-2387",module:"changshi",prompt:"法律的时间效力包括？",options:["生效时间、失效时间、溯及力", "仅生效时间", "仅失效时间", "仅溯及力"],answer:0,explanation:"法律的时间效力包括生效时间、失效时间和溯及力三个方面。"},{id:"cs-2388",module:"changshi",prompt:"权利与义务的关系是？",options:["对立统一", "完全对立", "完全统一", "没有关系"],answer:0,explanation:"权利与义务是对立统一的关系，相互依存、相互转化。"},{id:"cs-2389",module:"changshi",prompt:"法律责任的归责原则不包括？",options:["道德归责", "责任法定", "因果联系", "责任相当"],answer:0,explanation:"法律责任的归责原则包括责任法定原则、因果联系原则、责任相当原则、责任自负原则；道德归责不属于法律归责原则。"},{id:"cs-2390",module:"changshi",prompt:"法律责任的免除事由不包括？",options:["故意违法", "时效届满", "自首立功", "不起诉"],answer:0,explanation:"法律责任的免除事由包括时效届满、自首立功、不起诉、赦免等；故意违法不是免责事由。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-2391",module:"changshi",prompt:"《民法典》自何时施行？",options:["2020年5月28日", "2021年1月1日", "2020年10月1日", "2021年7月1日"],answer:1,explanation:"《民法典》于2020年5月28日通过，2021年1月1日起施行。"},{id:"cs-2392",module:"changshi",prompt:"《民法典》施行后，哪些法律同时废止？",options:["婚姻法、继承法、民法通则、收养法、担保法、合同法、物权法、侵权责任法、民法总则", "仅婚姻法和继承法", "仅合同法和物权法", "所有民事单行法"],answer:0,explanation:"《民法典》施行后，上述九部民事单行法同时废止。"},{id:"cs-2393",module:"changshi",prompt:"自然人的民事权利能力始于？",options:["出生", "年满8周岁", "年满18周岁", "受孕"],answer:0,explanation:"自然人的民事权利能力始于出生，终于死亡。"},{id:"cs-2394",module:"changshi",prompt:"胎儿是否具有民事权利能力？",options:["涉及遗产继承、接受赠与等胎儿利益保护的，胎儿视为具有民事权利能力", "一律没有", "一律有", "出生后才有"],answer:0,explanation:"《民法典》第16条规定了胎儿利益保护制度。"},{id:"cs-2395",module:"changshi",prompt:"自然人的民事行为能力分为？",options:["完全、限制、无民事行为能力", "完全和限制", "完全和无", "限制和无"],answer:0,explanation:"自然人的民事行为能力分为完全民事行为能力、限制民事行为能力和无民事行为能力。"},{id:"cs-2396",module:"changshi",prompt:"8周岁以上未成年人的民事行为能力是？",options:["完全民事行为能力", "限制民事行为能力", "无民事行为能力", "视情况而定"],answer:1,explanation:"8周岁以上未成年人为限制民事行为能力人，可实施纯获利益或与其年龄智力相适应的行为。"},{id:"cs-2397",module:"changshi",prompt:"不满8周岁的未成年人的民事行为能力是？",options:["完全民事行为能力", "限制民事行为能力", "无民事行为能力", "视情况而定"],answer:2,explanation:"不满8周岁的未成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。"},{id:"cs-2398",module:"changshi",prompt:"不能辨认自己行为的成年人为？",options:["完全民事行为能力人", "限制民事行为能力人", "无民事行为能力人", "视情况而定"],answer:2,explanation:"不能辨认自己行为的成年人为无民事行为能力人。"},{id:"cs-2399",module:"changshi",prompt:"法人成立的要件不包括？",options:["有自己的名称、组织机构、住所、财产或者经费", "依法成立", "有自己的意思机关", "必须盈利"],answer:3,explanation:"法人成立的要件包括依法成立、有自己的名称组织机构住所财产经费；法人可以是非营利性的。"},{id:"cs-2400",module:"changshi",prompt:"下列属于特别法人的是？",options:["有限责任公司", "机关法人", "基金会", "社会团体"],answer:1,explanation:"特别法人包括机关法人、农村集体经济组织法人、城镇农村的合作经济组织法人、基层群众性自治组织法人。"},{id:"cs-2401",module:"changshi",prompt:"意思表示的生效时间，以对话方式作出的为？",options:["相对人知道其内容时", "作出时", "发出时", "到达时"],answer:0,explanation:"以对话方式作出的意思表示，相对人知道其内容时生效。"},{id:"cs-2402",module:"changshi",prompt:"以非对话方式作出的意思表示，到达相对人时生效，这称为？",options:["到达主义", "发出主义", "知道主义", "投邮主义"],answer:0,explanation:"《民法典》第137条采取到达主义。"},{id:"cs-2403",module:"changshi",prompt:"无效民事法律行为的后果是？",options:["自始没有法律约束力", "自始有效", "效力待定", "可撤销"],answer:0,explanation:"无效的民事法律行为自始没有法律约束力。"},{id:"cs-2404",module:"changshi",prompt:"可撤销民事法律行为的撤销权行使期限（一般情形）为？",options:["自知道或应当知道撤销事由之日起1年内", "3年内", "5年内", "6个月内"],answer:0,explanation:"一般撤销权行使期限为1年；重大误解为90日；胁迫为自胁迫行为终止之日起1年。"},{id:"cs-2405",module:"changshi",prompt:"受胁迫的民事法律行为，撤销权行使期限为？",options:["自胁迫行为终止之日起1年内", "自行为成立之日起1年内", "3年内", "6个月内"],answer:0,explanation:"受胁迫的撤销权自胁迫行为终止之日起1年内行使。"},{id:"cs-2406",module:"changshi",prompt:"显失公平的民事法律行为，撤销权行使期限为？",options:["自知道或应当知道撤销事由之日起1年内", "90日内", "3年内", "6个月内"],answer:0,explanation:"显失公平的撤销权自知道或应当知道撤销事由之日起1年内行使。"},{id:"cs-2407",module:"changshi",prompt:"撤销权行使的最长期限为？",options:["自民事法律行为发生之日起5年内", "3年内", "10年内", "1年内"],answer:0,explanation:"当事人自民事法律行为发生之日起5年内没有行使撤销权的，撤销权消灭。"},{id:"cs-2408",module:"changshi",prompt:"代理人在代理权限内以被代理人名义实施的民事法律行为，其法律后果由谁承担？",options:["被代理人", "代理人", "第三人", "代理人和被代理人共同"],answer:0,explanation:"代理人在代理权限内以被代理人名义实施的法律行为，后果由被代理人承担。"},{id:"cs-2409",module:"changshi",prompt:"无权代理未经被代理人追认的，对被代理人不发生效力，其后果由谁承担？",options:["行为人", "被代理人", "第三人", "代理人和被代理人共同"],answer:0,explanation:"无权代理未经追认的，由行为人承担责任。"},{id:"cs-2410",module:"changshi",prompt:"表见代理的法律后果由谁承担？",options:["被代理人", "代理人", "第三人", "代理人和被代理人共同"],answer:0,explanation:"表见代理的后果由被代理人承担，被代理人可向代理人追偿。"},{id:"cs-2411",module:"changshi",prompt:"诉讼时效期间一般为？",options:["3年", "1年", "2年", "5年"],answer:0,explanation:"《民法典》规定普通诉讼时效期间为3年。"},{id:"cs-2412",module:"changshi",prompt:"诉讼时效期间自何时起算？",options:["权利人知道或应当知道权利受到损害以及义务人之日起", "权利受到损害之日", "义务人承认之日", "法院受理之日"],answer:0,explanation:"诉讼时效自权利人知道或应当知道权利受到损害以及义务人之日起计算。"},{id:"cs-2413",module:"changshi",prompt:"最长诉讼时效期间为？",options:["自权利受到损害之日起20年", "10年", "30年", "50年"],answer:0,explanation:"自权利受到损害之日起超过20年的，人民法院不予保护。"},{id:"cs-2414",module:"changshi",prompt:"下列哪种请求权不适用诉讼时效？",options:["请求停止侵害、排除妨碍、消除危险", "请求返还财产", "请求支付违约金", "请求赔偿损失"],answer:0,explanation:"物权请求权中的停止侵害、排除妨碍、消除危险等不适用诉讼时效。"},{id:"cs-2415",module:"changshi",prompt:"诉讼时效中止的事由发生在时效期间最后几个月内？",options:["6个月内", "3个月内", "1年内", "9个月内"],answer:0,explanation:"在诉讼时效期间的最后6个月内，因不可抗力等障碍不能行使请求权的，诉讼时效中止。"},{id:"cs-2416",module:"changshi",prompt:"诉讼时效中断后，时效期间如何计算？",options:["从中断、有关程序终结之日起重新计算", "继续计算", "重新起算但不超过20年", "顺延"],answer:0,explanation:"诉讼时效中断的，从中断、有关程序终结之日起，诉讼时效期间重新计算。"},{id:"cs-2417",module:"changshi",prompt:"物权的公示方法，动产为？",options:["交付", "登记", "占有改定", "指示交付"],answer:0,explanation:"动产物权的设立和转让自交付时发生效力。"},{id:"cs-2418",module:"changshi",prompt:"物权的公示方法，不动产为？",options:["登记", "交付", "占有", "合同生效"],answer:0,explanation:"不动产物权的设立、变更、转让和消灭经依法登记发生效力。"},{id:"cs-2419",module:"changshi",prompt:"用益物权的种类不包括？",options:["抵押权", "土地承包经营权", "建设用地使用权", "宅基地使用权"],answer:0,explanation:"用益物权包括土地承包经营权、建设用地使用权、宅基地使用权、居住权、地役权；抵押权属于担保物权。"},{id:"cs-2420",module:"changshi",prompt:"担保物权的种类不包括？",options:["地役权", "抵押权", "质权", "留置权"],answer:0,explanation:"担保物权包括抵押权、质权、留置权；地役权属于用益物权。"},{id:"cs-2421",module:"changshi",prompt:"抵押权自何时设立（不动产）？",options:["登记时", "合同生效时", "交付时", "占有"],answer:0,explanation:"不动产抵押权自登记时设立。"},{id:"cs-2422",module:"changshi",prompt:"抵押权自何时设立（动产）？",options:["合同生效时", "登记时", "交付时", "占有"],answer:0,explanation:"动产抵押权自抵押合同生效时设立，未经登记不得对抗善意第三人。"},{id:"cs-2423",module:"changshi",prompt:"质权自何时设立（动产）？",options:["出质人交付质押财产时", "合同生效时", "登记时", "占有改定"],answer:0,explanation:"动产质权自出质人交付质押财产时设立。"},{id:"cs-2424",module:"changshi",prompt:"留置权的成立条件不包括？",options:["债权人合法占有债务人的动产", "债务已届清偿期", "动产的占有与债权属于同一法律关系（企业间留置除外）", "必须经过登记"],answer:3,explanation:"留置权无需登记，其成立条件为合法占有、债务到期、同一法律关系（企业间留置除外）。"},{id:"cs-2425",module:"changshi",prompt:"合同的成立一般需要？",options:["要约和承诺", "书面形式", "公证", "登记"],answer:0,explanation:"合同一般经要约和承诺成立。"},{id:"cs-2426",module:"changshi",prompt:"要约的构成要件不包括？",options:["内容具体确定", "表明经受要约人承诺即受约束", "向希望缔约的相对人发出", "必须书面"],answer:3,explanation:"要约可以采用书面、口头等形式，不要求必须书面。"},{id:"cs-2427",module:"changshi",prompt:"合同生效与合同成立的关系是？",options:["合同成立是合同生效的前提，但成立的合同不一定生效", "二者完全相同", "二者没有关系", "生效的合同一定成立"],answer:0,explanation:"合同成立是事实判断，合同生效是价值判断；成立的合同不一定生效。"},{id:"cs-2428",module:"changshi",prompt:"无效合同的情形不包括？",options:["因重大误解订立", "违反法律、行政法规的强制性规定", "恶意串通损害他人合法权益", "违背公序良俗"],answer:0,explanation:"因重大误解订立的合同是可撤销合同，不是无效合同。"},{id:"cs-2429",module:"changshi",prompt:"合同解除的方式不包括？",options:["自动解除", "协商解除", "约定解除", "法定解除"],answer:0,explanation:"合同解除的方式包括协商解除、约定解除、法定解除；自动解除不是解除方式。"},{id:"cs-2430",module:"changshi",prompt:"合同的权利义务终止的情形不包括？",options:["合同被撤销", "债务已经履行", "债务相互抵销", "债权人免除债务"],answer:0,explanation:"合同被撤销自始没有法律约束力，不属于合同权利义务终止的情形。"},{id:"cs-2431",module:"changshi",prompt:"违约责任的承担方式不包括？",options:["赔礼道歉", "继续履行", "采取补救措施", "赔偿损失"],answer:0,explanation:"违约责任的承担方式包括继续履行、采取补救措施、赔偿损失、违约金、定金；赔礼道歉属于侵权责任方式。"},{id:"cs-2432",module:"changshi",prompt:"定金数额不得超过主合同标的额的？",options:["20%", "10%", "30%", "50%"],answer:0,explanation:"定金数额由当事人约定，但不得超过主合同标的额的20%。"},{id:"cs-2433",module:"changshi",prompt:"定金与违约金能否并用？",options:["不能并用，只能选择适用其一", "可以并用", "必须并用", "由法院决定"],answer:0,explanation:"定金与违约金不能并用，当事人只能选择适用其一。"},{id:"cs-2434",module:"changshi",prompt:"人格权的种类不包括？",options:["债权", "生命权", "身体权", "健康权"],answer:0,explanation:"人格权包括生命权、身体权、健康权、姓名权、肖像权、名誉权、荣誉权、隐私权等；债权是独立的权利类型。"},{id:"cs-2435",module:"changshi",prompt:"个人信息保护的原则不包括？",options:["公开透明", "合法、正当、必要", "目的限制", "无限使用"],answer:3,explanation:"个人信息处理应遵循合法、正当、必要、目的限制、公开透明等原则；无限使用违反个人信息保护原则。"},{id:"cs-2436",module:"changshi",prompt:"婚姻无效的情形不包括？",options:["因胁迫结婚", "重婚", "有禁止结婚的亲属关系", "未到法定婚龄"],answer:0,explanation:"因胁迫结婚的属于可撤销婚姻，不是无效婚姻。"},{id:"cs-2437",module:"changshi",prompt:"可撤销婚姻的情形包括？",options:["因胁迫结婚、一方患有重大疾病未在结婚登记前如实告知", "重婚", "有禁止结婚的亲属关系", "未到法定婚龄"],answer:0,explanation:"《民法典》规定可撤销婚姻包括因胁迫结婚和一方患有重大疾病未如实告知两种情形。"},{id:"cs-2438",module:"changshi",prompt:"遗产的清偿顺序，先于税款的是？",options:["继承费用和债务", "税款", "债务", "继承费用"],answer:0,explanation:"分割遗产应当清偿被继承人依法应当缴纳的税款和债务，继承费用和债务优先于税款。"},{id:"cs-2439",module:"changshi",prompt:"侵权责任的归责原则不包括？",options:["无过错责任原则", "过错责任原则", "过错推定责任原则", "公平责任原则"],answer:3,explanation:"侵权责任的归责原则包括过错责任原则、过错推定责任原则、无过错责任原则；公平责任是损失分担规则，不是归责原则。"},{id:"cs-2440",module:"changshi",prompt:"高空抛物坠物的责任规则是？",options:["侵权人承担；难以确定侵权人的，由可能加害的建筑物使用人补偿（能证明自己不是侵权人的除外）", "物业全部承担", "全体业主平均分担", "无人承担"],answer:0,explanation:"《民法典》第1254条明确了高空抛物坠物的责任规则。"},{id:"cs-2441",module:"changshi",prompt:"刑法的基本原则不包括？",options:["罪刑法定原则", "适用刑法人人平等原则", "罪责刑相适应原则", "无罪推定原则"],answer:3,explanation:"刑法的基本原则包括罪刑法定、适用刑法人人平等、罪责刑相适应；无罪推定是刑事诉讼法原则。"},{id:"cs-2442",module:"changshi",prompt:"罪刑法定原则的含义是？",options:["法无明文规定不为罪，法无明文规定不处罚", "有罪必罚", "从重从快", "坦白从宽"],answer:0,explanation:"罪刑法定原则要求犯罪的成立和刑罚的适用必须以法律的明文规定为前提。"},{id:"cs-2443",module:"changshi",prompt:"适用刑法人人平等原则的含义是？",options:["对任何人犯罪，在适用法律上一律平等，不允许任何人有超越法律的特权", "刑罚相同", "处罚相同", "量刑相同"],answer:0,explanation:"适用刑法人人平等原则要求对任何人犯罪在适用法律上一律平等。"},{id:"cs-2444",module:"changshi",prompt:"罪责刑相适应原则的含义是？",options:["刑罚的轻重应当与犯罪分子所犯罪行和承担的刑事责任相适应", "刑罚越重越好", "刑罚越轻越好", "刑罚与身份相适应"],answer:0,explanation:"罪责刑相适应原则要求刑罚的轻重与犯罪行为的社会危害性和行为人的人身危险性相适应。"},{id:"cs-2445",module:"changshi",prompt:"犯罪的三个基本特征是？",options:["社会危害性、刑事违法性、应受刑罚惩罚性", "主观性、客观性、社会性", "违法性、有责性、可罚性", "危害性、违法性、惩罚性"],answer:0,explanation:"犯罪具有严重社会危害性、刑事违法性、应受刑罚惩罚性三个基本特征。"},{id:"cs-2446",module:"changshi",prompt:"犯罪构成的要件不包括？",options:["犯罪客体", "犯罪客观方面", "犯罪主体", "犯罪动机"],answer:3,explanation:"犯罪构成要件包括犯罪客体、犯罪客观方面、犯罪主体、犯罪主观方面；犯罪动机不是构成要件。"},{id:"cs-2447",module:"changshi",prompt:"犯罪主体的要件不包括？",options:["达到刑事责任年龄", "具有刑事责任能力", "实施了危害社会的行为", "必须是中国公民"],answer:3,explanation:"犯罪主体可以是自然人或单位，不限于中国公民。"},{id:"cs-2448",module:"changshi",prompt:"犯罪主观方面的要件不包括？",options:["故意", "过失", "目的", "动机"],answer:3,explanation:"犯罪主观方面包括故意、过失、目的；动机不是构成要件。"},{id:"cs-2449",module:"changshi",prompt:"直接故意的认识因素是？",options:["明知自己的行为会发生危害社会的结果", "应当预见而没有预见", "已经预见而轻信能够避免", "不知道自己的行为"],answer:0,explanation:"直接故意是明知自己的行为会发生危害社会的结果，并且希望这种结果发生。"},{id:"cs-2450",module:"changshi",prompt:"间接故意的意志因素是？",options:["放任危害结果的发生", "希望危害结果的发生", "反对危害结果的发生", "不知道危害结果"],answer:0,explanation:"间接故意是明知自己的行为可能发生危害社会的结果，并且放任这种结果发生。"},{id:"cs-2451",module:"changshi",prompt:"过于自信的过失是指？",options:["已经预见而轻信能够避免", "应当预见而没有预见", "明知会发生而希望发生", "明知会发生而放任"],answer:0,explanation:"过于自信的过失是已经预见自己的行为可能发生危害结果而轻信能够避免。"},{id:"cs-2452",module:"changshi",prompt:"疏忽大意的过失是指？",options:["应当预见而没有预见", "已经预见而轻信能够避免", "明知会发生而希望发生", "明知会发生而放任"],answer:0,explanation:"疏忽大意的过失是应当预见自己的行为可能发生危害结果而没有预见。"},{id:"cs-2453",module:"changshi",prompt:"正当防卫的起因条件是？",options:["存在现实的不法侵害", "存在假想的不法侵害", "存在一般违法行为", "存在犯罪行为"],answer:0,explanation:"正当防卫的起因条件是存在现实的不法侵害。"},{id:"cs-2454",module:"changshi",prompt:"正当防卫的时间条件是？",options:["不法侵害正在进行", "不法侵害尚未开始", "不法侵害已经结束", "不法侵害可能发生"],answer:0,explanation:"正当防卫必须针对正在进行的不法侵害。"},{id:"cs-2455",module:"changshi",prompt:"正当防卫的对象条件是？",options:["不法侵害人本人", "第三人", "不法侵害人的家属", "任何人"],answer:0,explanation:"正当防卫只能针对不法侵害人本人进行。"},{id:"cs-2456",module:"changshi",prompt:"防卫过当的罪过形式一般为？",options:["过失", "故意", "意外事件", "不可抗力"],answer:0,explanation:"防卫过当的罪过形式一般为过失，也可能是间接故意。"},{id:"cs-2457",module:"changshi",prompt:"特殊防卫（无限防卫权）适用于？",options:["行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪", "所有犯罪", "一般违法行为", "财产犯罪"],answer:0,explanation:"对严重危及人身安全的暴力犯罪进行防卫，造成不法侵害人伤亡的，不属于防卫过当。"},{id:"cs-2458",module:"changshi",prompt:"紧急避险的限度条件是？",options:["不能超过必要限度造成不应有的损害", "可以超过必要限度", "没有限度", "由法院决定"],answer:0,explanation:"紧急避险不能超过必要限度造成不应有的损害。"},{id:"cs-2459",module:"changshi",prompt:"紧急避险与正当防卫的区别不包括？",options:["紧急避险针对不法侵害人，正当防卫针对第三人", "紧急避险针对危险源，正当防卫针对不法侵害人", "紧急避险牺牲较小利益保护较大利益", "紧急避险的对象可以是第三人"],answer:0,explanation:"紧急避险针对的是危险源（可以是第三人利益），正当防卫针对的是不法侵害人本人。"},{id:"cs-2460",module:"changshi",prompt:"犯罪预备的特征不包括？",options:["已经着手实行犯罪", "为了犯罪准备工具、制造条件", "由于意志以外的原因未能着手", "具有犯罪意图"],answer:0,explanation:"犯罪预备是已经为犯罪做准备但尚未着手实行；已经着手实行的是犯罪未遂。"},{id:"cs-2461",module:"changshi",prompt:"犯罪未遂的特征不包括？",options:["已经着手实行犯罪", "犯罪未得逞", "由于犯罪分子意志以外的原因未得逞", "自动放弃犯罪"],answer:3,explanation:"自动放弃犯罪的是犯罪中止，不是犯罪未遂。"},{id:"cs-2462",module:"changshi",prompt:"犯罪中止的特征不包括？",options:["在犯罪过程中自动放弃犯罪", "自动有效地防止犯罪结果发生", "由于意志以外的原因未得逞", "具有自动性"],answer:2,explanation:"由于意志以外的原因未得逞的是犯罪未遂，不是犯罪中止。"},{id:"cs-2463",module:"changshi",prompt:"犯罪中止的处罚原则是？",options:["没有造成损害的应当免除处罚，造成损害的应当减轻处罚", "应当从轻处罚", "应当从重处罚", "可以免除处罚"],answer:0,explanation:"犯罪中止没有造成损害的应当免除处罚，造成损害的应当减轻处罚。"},{id:"cs-2464",module:"changshi",prompt:"犯罪未遂的处罚原则是？",options:["可以比照既遂犯从轻或者减轻处罚", "应当免除处罚", "应当从重处罚", "可以免除处罚"],answer:0,explanation:"犯罪未遂可以比照既遂犯从轻或者减轻处罚。"},{id:"cs-2465",module:"changshi",prompt:"犯罪预备的处罚原则是？",options:["可以比照既遂犯从轻、减轻或者免除处罚", "应当免除处罚", "应当从重处罚", "可以免除处罚"],answer:0,explanation:"犯罪预备可以比照既遂犯从轻、减轻或者免除处罚。"},{id:"cs-2466",module:"changshi",prompt:"共同犯罪的成立条件不包括？",options:["二人以上", "有共同故意", "有共同行为", "有共同目的"],answer:3,explanation:"共同犯罪的成立条件是二人以上、有共同故意、有共同行为；共同目的不是必要条件。"},{id:"cs-2467",module:"changshi",prompt:"胁从犯的处罚原则是？",options:["应当按照其犯罪情节减轻或者免除处罚", "应当从重处罚", "免除处罚", "不受处罚"],answer:0,explanation:"胁从犯应当按照其犯罪情节减轻或者免除处罚。"},{id:"cs-2468",module:"changshi",prompt:"教唆犯的处罚原则是？",options:["按照其在共同犯罪中所起的作用处罚；教唆不满18周岁的人犯罪的应当从重处罚；被教唆的人没有犯被教唆的罪的可以从轻或者减轻处罚", "一律从重处罚", "一律免除处罚", "一律从轻处罚"],answer:0,explanation:"教唆犯按照其在共同犯罪中所起的作用处罚，教唆未成年人犯罪的从重处罚。"},{id:"cs-2469",module:"changshi",prompt:"单位犯罪的双罚制是指？",options:["对单位判处罚金，对直接负责的主管人员和其他直接责任人员判处刑罚", "仅对单位判处罚金", "仅对个人判处罚金", "仅对单位判处罚金和个人判处刑罚"],answer:0,explanation:"单位犯罪实行双罚制，对单位判处罚金，对直接负责的主管人员和其他直接责任人员判处刑罚。"},{id:"cs-2470",module:"changshi",prompt:"有期徒刑的期限一般为？",options:["6个月以上15年以下", "1个月以上6个月以下", "3个月以上2年以下", "1年以上20年以下"],answer:0,explanation:"有期徒刑的期限一般为6个月以上15年以下，数罪并罚不超过20年或25年。"},{id:"cs-2471",module:"changshi",prompt:"不适用死刑的对象不包括？",options:["怀孕的妇女", "犯罪时不满18周岁的人", "审判时怀孕的妇女", "审判时已满75周岁的人（一般）"],answer:3,explanation:"审判时已满75周岁的人一般不适用死刑，但以特别残忍手段致人死亡的除外。"},{id:"cs-2472",module:"changshi",prompt:"剥夺政治权利的内容不包括？",options:["担任国有公司、企业、事业单位和人民团体领导职务的权利", "选举权和被选举权", "言论、出版、集会、结社、游行、示威自由的权利", "担任国家机关职务的权利"],answer:0,explanation:"剥夺政治权利的内容包括选举权和被选举权、言论出版集会结社游行示威自由的权利、担任国家机关职务的权利、担任国有公司企业事业单位和人民团体领导职务的权利。"},{id:"cs-2473",module:"changshi",prompt:"没收财产的适用对象是？",options:["犯罪分子个人所有财产的一部分或全部", "犯罪分子家属的财产", "犯罪分子的全部财产", "犯罪分子的合法收入"],answer:0,explanation:"没收财产是没收犯罪分子个人所有财产的一部分或者全部。"},{id:"cs-2474",module:"changshi",prompt:"累犯的构成条件不包括？",options:["前罪和后罪都是故意犯罪", "前罪和后罪都被判处有期徒刑以上刑罚", "后罪发生在前罪刑罚执行完毕或赦免后5年内", "前罪和后罪都是过失犯罪"],answer:3,explanation:"累犯的前罪和后罪都必须是故意犯罪，过失犯罪不构成累犯。"},{id:"cs-2475",module:"changshi",prompt:"自首的成立条件不包括？",options:["自动投案", "如实供述自己的罪行", "主动交代司法机关还未掌握的本人其他罪行", "主动赔偿损失"],answer:3,explanation:"自首的成立条件是自动投案和如实供述自己的罪行；主动赔偿损失不是自首的成立条件。"},{id:"cs-2476",module:"changshi",prompt:"数罪并罚时，管制最高不超过？",options:["3年", "2年", "1年", "5年"],answer:0,explanation:"数罪并罚时，管制最高不超过3年。"},{id:"cs-2477",module:"changshi",prompt:"数罪并罚时，拘役最高不超过？",options:["1年", "6个月", "2年", "3年"],answer:0,explanation:"数罪并罚时，拘役最高不超过1年。"},{id:"cs-2478",module:"changshi",prompt:"数罪并罚时，有期徒刑总和刑期不满35年的最高不超过？",options:["20年", "15年", "25年", "30年"],answer:0,explanation:"数罪并罚时，有期徒刑总和刑期不满35年的最高不超过20年。"},{id:"cs-2479",module:"changshi",prompt:"数罪并罚时，有期徒刑总和刑期在35年以上的最高不超过？",options:["25年", "20年", "30年", "35年"],answer:0,explanation:"数罪并罚时，有期徒刑总和刑期在35年以上的最高不超过25年。"},{id:"cs-2480",module:"changshi",prompt:"缓刑的适用条件不包括？",options:["犯罪情节较轻", "有悔罪表现", "没有再犯罪的危险", "必须判处3年以上有期徒刑"],answer:3,explanation:"缓刑适用于被判处拘役或3年以下有期徒刑的犯罪分子；判处3年以上有期徒刑的不适用缓刑。"},{id:"cs-2481",module:"changshi",prompt:"缓刑的考验期（拘役）为？",options:["原判刑期以上1年以下，但不能少于2个月", "原判刑期以上5年以下", "原判刑期以上3年以下", "原判刑期以上2年以下"],answer:0,explanation:"拘役的缓刑考验期为原判刑期以上1年以下，但不能少于2个月。"},{id:"cs-2482",module:"changshi",prompt:"缓刑的考验期（有期徒刑）为？",options:["原判刑期以上5年以下，但不能少于1年", "原判刑期以上3年以下", "原判刑期以上2年以下", "原判刑期以上10年以下"],answer:0,explanation:"有期徒刑的缓刑考验期为原判刑期以上5年以下，但不能少于1年。"},{id:"cs-2483",module:"changshi",prompt:"减刑的适用条件不包括？",options:["认真遵守监规，接受教育改造", "确有悔改表现", "有立功表现", "必须判处无期徒刑"],answer:3,explanation:"减刑适用于被判处管制、拘役、有期徒刑、无期徒刑的犯罪分子；不限于无期徒刑。"},{id:"cs-2484",module:"changshi",prompt:"减刑后实际执行的刑期（无期徒刑）不能少于？",options:["13年", "10年", "15年", "20年"],answer:0,explanation:"无期徒刑减刑后实际执行的刑期不能少于13年。"},{id:"cs-2485",module:"changshi",prompt:"假释的适用条件不包括？",options:["被判处有期徒刑或无期徒刑", "认真遵守监规，接受教育改造", "确有悔改表现，没有再犯罪的危险", "必须已执行原判刑期的一半以上"],answer:3,explanation:"假释的适用条件包括被判处有期徒刑或无期徒刑、认真遵守监规、确有悔改表现等；已执行刑期的要求因刑种而异。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-2486",module:"changshi",prompt:"承诺生效时合同处于什么状态？",options:["合同成立", "合同生效", "合同履行", "合同解除"],answer:0,explanation:"承诺生效时合同成立，但法律另有规定或当事人另有约定的除外。"},{id:"cs-2487",module:"changshi",prompt:"人格权的行使限制是？",options:["放弃、转让或者继承", "行使", "保护", "主张"],answer:0,explanation:"人格权不得放弃、转让或者继承。"},{id:"cs-2488",module:"changshi",prompt:"协议离婚中离婚冷静期的期限为？",options:["30日", "15日", "60日", "90日"],answer:0,explanation:"协议离婚须经过30日冷静期，期满后30日内双方共同申请发证。"},{id:"cs-2489",module:"changshi",prompt:"死刑缓期执行的考验期为？",options:["2年", "1年", "3年", "5年"],answer:0,explanation:"对于应当判处死刑的犯罪分子，如果不是必须立即执行的，可以判处死刑同时宣告缓期2年执行。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-2490",module:"changshi",prompt:"行政法的基本原则不包括？",options:["罪刑法定原则", "合法行政原则", "合理行政原则", "程序正当原则"],answer:0,explanation:"行政法的基本原则包括合法行政、合理行政、程序正当、高效便民、诚实守信、权责统一；罪刑法定是刑法原则。"},{id:"cs-2491",module:"changshi",prompt:"合法行政原则的具体要求不包括？",options:["行政机关必须遵守宪法和法律", "行政机关必须依照法律授权行使职权", "行政机关可以超越法律授权", "行政机关不得法外设定权力"],answer:2,explanation:"合法行政原则要求行政机关遵守法律、依照法律授权行使职权，不得超越法律授权。"},{id:"cs-2492",module:"changshi",prompt:"合理行政原则的具体要求不包括？",options:["公平公正", "考虑相关因素", "比例原则", "绝对平等"],answer:3,explanation:"合理行政原则要求公平公正、考虑相关因素、比例原则；绝对平等不是合理行政的要求。"},{id:"cs-2493",module:"changshi",prompt:"比例原则的内容不包括？",options:["适当性", "必要性", "均衡性", "绝对性"],answer:3,explanation:"比例原则包括适当性、必要性、均衡性；绝对性不是比例原则的内容。"},{id:"cs-2494",module:"changshi",prompt:"程序正当原则的具体要求不包括？",options:["信息公开", "回避", "听证", "秘密裁决"],answer:3,explanation:"程序正当原则要求信息公开、回避、听证等；秘密裁决违反程序正当原则。"},{id:"cs-2495",module:"changshi",prompt:"行政行为的成立要件不包括？",options:["行政主体", "行政相对人", "意思表示", "司法程序"],answer:3,explanation:"行政行为的成立要件包括行政主体、行政相对人、意思表示；司法程序不是成立要件。"},{id:"cs-2496",module:"changshi",prompt:"行政行为的效力内容包括？",options:["公定力、确定力、拘束力、执行力", "仅公定力", "仅确定力", "仅拘束力"],answer:0,explanation:"行政行为的效力内容包括公定力、确定力、拘束力、执行力。"},{id:"cs-2497",module:"changshi",prompt:"行政行为的公定力是指？",options:["行政行为一经作出即推定合法有效", "行政行为一经作出即确定不变", "行政行为对相对人有拘束力", "行政行为可以强制执行"],answer:0,explanation:"公定力是指行政行为一经作出即推定合法有效，未经有权机关撤销前应推定有效。"},{id:"cs-2498",module:"changshi",prompt:"行政行为的确定力是指？",options:["行政行为一经作出即确定不变，非经法定程序不得变更或撤销", "行政行为一经作出即推定合法有效", "行政行为对相对人有拘束力", "行政行为可以强制执行"],answer:0,explanation:"确定力是指行政行为一经作出即确定不变，非经法定程序不得变更或撤销。"},{id:"cs-2499",module:"changshi",prompt:"行政行为的拘束力是指？",options:["行政行为对相对人和行政主体都有拘束力", "行政行为一经作出即推定合法有效", "行政行为一经作出即确定不变", "行政行为可以强制执行"],answer:0,explanation:"拘束力是指行政行为对相对人和行政主体都有拘束力，双方都应遵守。"},{id:"cs-2500",module:"changshi",prompt:"行政行为的执行力是指？",options:["行政行为具有强制执行的法律效力", "行政行为一经作出即推定合法有效", "行政行为一经作出即确定不变", "行政行为对相对人有拘束力"],answer:0,explanation:"执行力是指行政行为具有强制执行的法律效力。"},{id:"cs-2501",module:"changshi",prompt:"行政行为的无效情形不包括？",options:["行政行为程序轻微违法", "行政行为有实施主体不具有行政主体资格等重大且明显违法情形", "行政行为没有法律依据", "行政行为明显超越职权"],answer:0,explanation:"行政行为程序轻微违法属于可撤销情形，不是无效情形。"},{id:"cs-2502",module:"changshi",prompt:"行政行为的可撤销情形不包括？",options:["行政行为有实施主体不具有行政主体资格等重大且明显违法情形", "主要证据不足", "适用法律、法规错误", "违反法定程序"],answer:0,explanation:"重大且明显违法属于无效情形，不是可撤销情形。"},{id:"cs-2503",module:"changshi",prompt:"行政许可的种类不包括？",options:["行政确认", "普通许可", "特许", "认可"],answer:0,explanation:"行政许可的种类包括普通许可、特许、认可、核准、登记；行政确认是独立的行政行为类型。"},{id:"cs-2504",module:"changshi",prompt:"行政许可的设定权不包括？",options:["国务院部门规章", "法律", "行政法规", "地方性法规"],answer:0,explanation:"行政许可的设定权包括法律、行政法规、地方性法规、省级政府规章（临时性）；国务院部门规章不得设定行政许可。"},{id:"cs-2505",module:"changshi",prompt:"行政许可的实施程序不包括？",options:["听证", "申请", "受理", "审查决定"],answer:0,explanation:"行政许可的实施程序包括申请、受理、审查决定、听证等；听证是特殊程序，不是一般程序。"},{id:"cs-2506",module:"changshi",prompt:"行政许可的听证程序适用于？",options:["涉及公共利益的重大行政许可事项", "所有行政许可", "仅涉及个人利益的行政许可", "仅涉及企业利益的行政许可"],answer:0,explanation:"涉及公共利益的重大行政许可事项，行政机关应当向社会公告并举行听证。"},{id:"cs-2507",module:"changshi",prompt:"行政处罚的设定权不包括？",options:["国务院部门规章", "法律", "行政法规", "地方性法规"],answer:0,explanation:"行政处罚的设定权包括法律、行政法规、地方性法规、部门规章（警告、通报批评或一定数额罚款）、地方政府规章（警告、通报批评或一定数额罚款）。"},{id:"cs-2508",module:"changshi",prompt:"行政处罚的简易程序适用于？",options:["违法事实确凿并有法定依据，对公民处以二百元以下、对法人或者其他组织处以三千元以下罚款或者警告的行政处罚", "所有行政处罚", "仅涉及重大利益的行政处罚", "仅涉及人身自由的行政处罚"],answer:0,explanation:"行政处罚的简易程序适用于违法事实确凿并有法定依据，对公民处以二百元以下、对法人或者其他组织处以三千元以下罚款或者警告的行政处罚。"},{id:"cs-2509",module:"changshi",prompt:"行政处罚的普通程序适用于？",options:["除简易程序外的其他行政处罚", "仅简易程序", "仅听证程序", "仅强制执行"],answer:0,explanation:"行政处罚的普通程序适用于除简易程序外的其他行政处罚。"},{id:"cs-2510",module:"changshi",prompt:"行政处罚的听证程序适用于？",options:["较大数额罚款、没收较大数额违法所得、降低资质等级、吊销许可证件、责令停产停业、责令关闭、限制从业等", "所有行政处罚", "仅简易程序", "仅普通程序"],answer:0,explanation:"行政处罚的听证程序适用于较大数额罚款、没收较大数额违法所得、降低资质等级、吊销许可证件、责令停产停业、责令关闭、限制从业等。"},{id:"cs-2511",module:"changshi",prompt:"行政强制的种类不包括？",options:["行政拘留", "限制公民人身自由", "查封场所、设施或者财物", "扣押财物"],answer:0,explanation:"行政强制的种类包括限制公民人身自由、查封场所设施或者财物、扣押财物、冻结存款汇款等；行政拘留是行政处罚。"},{id:"cs-2512",module:"changshi",prompt:"行政强制措施的设定权不包括？",options:["国务院部门规章", "法律", "行政法规", "地方性法规"],answer:0,explanation:"行政强制措施的设定权包括法律、行政法规、地方性法规；国务院部门规章不得设定行政强制措施。"},{id:"cs-2513",module:"changshi",prompt:"行政强制执行的设定权是？",options:["法律", "行政法规", "地方性法规", "部门规章"],answer:0,explanation:"行政强制执行由法律设定。"},{id:"cs-2514",module:"changshi",prompt:"行政强制执行的申请期限为？",options:["当事人在法定期限内不申请行政复议或者提起行政诉讼，又不履行行政决定的，没有行政强制执行权的行政机关可以自期限届满之日起3个月内申请人民法院强制执行", "6个月内", "1年内", "2年内"],answer:0,explanation:"当事人在法定期限内不申请行政复议或者提起行政诉讼，又不履行行政决定的，没有行政强制执行权的行政机关可以自期限届满之日起3个月内申请人民法院强制执行。"},{id:"cs-2515",module:"changshi",prompt:"行政复议的申请期限为？",options:["知道该行政行为之日起60日内", "30日内", "90日内", "6个月内"],answer:0,explanation:"行政复议申请期限为知道该行政行为之日起60日内。"},{id:"cs-2516",module:"changshi",prompt:"行政复议的受理期限为？",options:["收到申请之日起5日内", "10日内", "15日内", "30日内"],answer:0,explanation:"行政复议机关收到申请后5日内进行审查，决定是否受理。"},{id:"cs-2517",module:"changshi",prompt:"行政复议的审理期限为？",options:["受理申请之日起60日内", "30日内", "90日内", "6个月内"],answer:0,explanation:"行政复议机关应当自受理申请之日起60日内作出行政复议决定。"},{id:"cs-2518",module:"changshi",prompt:"行政复议决定的种类不包括？",options:["行政赔偿决定", "维持决定", "撤销决定", "变更决定"],answer:0,explanation:"行政复议决定的种类包括维持决定、撤销决定、变更决定、确认违法决定、责令履行决定；行政赔偿决定是独立类型。"},{id:"cs-2519",module:"changshi",prompt:"行政复议的终局决定适用于？",options:["省级人民政府确认自然资源所有权或使用权的行政复议决定", "所有行政复议决定", "仅涉及人身自由的行政复议决定", "仅涉及财产权的行政复议决定"],answer:0,explanation:"省级人民政府确认自然资源所有权或使用权的行政复议决定为终局决定。"},{id:"cs-2520",module:"changshi",prompt:"行政诉讼的受案范围不包括？",options:["抽象行政行为", "行政处罚", "行政强制措施", "行政许可"],answer:0,explanation:"行政诉讼的受案范围包括行政处罚、行政强制措施、行政许可等具体行政行为；抽象行政行为一般不属于受案范围。"},{id:"cs-2521",module:"changshi",prompt:"行政诉讼的管辖不包括？",options:["专属管辖", "级别管辖", "地域管辖", "裁定管辖"],answer:0,explanation:"行政诉讼的管辖包括级别管辖、地域管辖、裁定管辖；专属管辖是民事诉讼的管辖类型。"},{id:"cs-2522",module:"changshi",prompt:"行政诉讼的原告资格是？",options:["行政行为的相对人以及其他与行政行为有利害关系的公民、法人或者其他组织", "仅行政行为的相对人", "仅利害关系人", "任何人"],answer:0,explanation:"行政诉讼的原告资格是行政行为的相对人以及其他与行政行为有利害关系的公民、法人或者其他组织。"},{id:"cs-2523",module:"changshi",prompt:"行政诉讼的被告一般是？",options:["作出行政行为的行政机关", "行政机关的工作人员", "行政机关的上级机关", "行政机关的同级党委"],answer:0,explanation:"行政诉讼的被告一般是作出行政行为的行政机关。"},{id:"cs-2524",module:"changshi",prompt:"行政诉讼的举证责任由谁承担？",options:["被告", "原告", "第三人", "法院"],answer:0,explanation:"行政诉讼的举证责任由被告承担，即被告对作出的行政行为负有举证责任。"},{id:"cs-2525",module:"changshi",prompt:"行政诉讼的起诉期限一般为？",options:["知道或者应当知道作出行政行为之日起6个月内", "3个月内", "60日内", "1年内"],answer:0,explanation:"行政诉讼的起诉期限一般为知道或者应当知道作出行政行为之日起6个月内。"},{id:"cs-2526",module:"changshi",prompt:"经过行政复议后提起行政诉讼的期限为？",options:["收到复议决定书之日起15日内", "30日内", "60日内", "6个月内"],answer:0,explanation:"经过行政复议后，对复议决定不服的，可以在收到复议决定书之日起15日内向人民法院提起行政诉讼。"},{id:"cs-2527",module:"changshi",prompt:"行政诉讼的判决种类不包括？",options:["行政赔偿判决", "驳回诉讼请求判决", "撤销判决", "变更判决"],answer:0,explanation:"行政诉讼的判决种类包括驳回诉讼请求判决、撤销判决、变更判决、确认违法判决、责令履行判决等；行政赔偿判决是独立类型。"},{id:"cs-2528",module:"changshi",prompt:"行政诉讼中，法院对行政行为的审查范围是？",options:["合法性审查，明显不当的也可以撤销", "仅合法性审查", "仅合理性审查", "全面审查"],answer:0,explanation:"行政诉讼中，法院对行政行为进行合法性审查，明显不当的也可以撤销。"},{id:"cs-2529",module:"changshi",prompt:"行政诉讼中，法院可以判决变更的情形是？",options:["行政处罚明显不当，或者其他行政行为涉及对款额的确定、认定确有不当", "所有行政行为", "仅涉及人身自由的行政行为", "仅涉及财产权的行政行为"],answer:0,explanation:"行政诉讼中，法院可以判决变更的情形是行政处罚明显不当，或者其他行政行为涉及对款额的确定、认定确有不当。"},{id:"cs-2530",module:"changshi",prompt:"国家赔偿的归责原则是？",options:["违法归责原则为主，结果归责原则为辅", "过错归责原则", "无过错归责原则", "公平归责原则"],answer:0,explanation:"国家赔偿的归责原则是违法归责原则为主，结果归责原则为辅。"},{id:"cs-2531",module:"changshi",prompt:"国家赔偿的范围不包括？",options:["精神损害赔偿（严重后果的）", "人身自由赔偿", "生命健康赔偿", "财产损失赔偿"],answer:0,explanation:"国家赔偿的范围包括人身自由赔偿、生命健康赔偿、财产损失赔偿；精神损害赔偿仅在造成严重后果时适用。"},{id:"cs-2532",module:"changshi",prompt:"国家赔偿的义务机关是？",options:["行使职权侵犯公民、法人和其他组织合法权益的行政机关或司法机关", "财政部门", "上级机关", "同级党委"],answer:0,explanation:"国家赔偿的义务机关是行使职权侵犯公民、法人和其他组织合法权益的行政机关或司法机关。"},{id:"cs-2533",module:"changshi",prompt:"国家赔偿的请求时效为？",options:["知道或者应当知道其合法权益被侵犯之日起2年内", "1年内", "3年内", "6个月内"],answer:0,explanation:"国家赔偿的请求时效为知道或者应当知道其合法权益被侵犯之日起2年内。"},{id:"cs-2534",module:"changshi",prompt:"行政赔偿的程序不包括？",options:["司法赔偿程序", "行政赔偿先行处理程序", "行政复议程序", "行政诉讼程序"],answer:0,explanation:"行政赔偿的程序包括行政赔偿先行处理程序、行政复议程序、行政诉讼程序；司法赔偿程序是刑事赔偿的程序。"},{id:"cs-2535",module:"changshi",prompt:"公务员的录用程序不包括？",options:["政审（政治考察）", "笔试", "面试", "体检"],answer:0,explanation:"公务员的录用程序包括发布招考公告、报名与资格审查、考试（笔试面试）、体检、考察（政审）、公示等；政审是考察环节，不是独立程序。"},{id:"cs-2536",module:"changshi",prompt:"公务员的处分期间（警告）为？",options:["6个月", "12个月", "18个月", "24个月"],answer:0,explanation:"警告的处分期间为6个月。"},{id:"cs-2537",module:"changshi",prompt:"公务员的处分期间（记过）为？",options:["12个月", "6个月", "18个月", "24个月"],answer:0,explanation:"记过的处分期间为12个月。"},{id:"cs-2538",module:"changshi",prompt:"公务员的处分期间（记大过）为？",options:["18个月", "6个月", "12个月", "24个月"],answer:0,explanation:"记大过的处分期间为18个月。"},{id:"cs-2539",module:"changshi",prompt:"公务员的处分期间（降级、撤职）为？",options:["24个月", "6个月", "12个月", "18个月"],answer:0,explanation:"降级、撤职的处分期间为24个月。"},{id:"cs-2540",module:"changshi",prompt:"公务员对涉及本人的人事处理不服的，可以申请？",options:["复核或申诉", "行政复议", "行政诉讼", "仲裁"],answer:0,explanation:"公务员对涉及本人的人事处理不服的，可以申请复核或申诉。"},{id:"cs-2541",module:"changshi",prompt:"劳动法的基本原则不包括？",options:["按劳分配原则", "劳动自由原则", "劳动条件基准化原则", "劳动力资源市场化配置原则"],answer:0,explanation:"劳动法的基本原则包括劳动自由原则、劳动条件基准化原则、劳动力资源市场化配置原则、劳动关系协调的契约化原则；按劳分配是分配原则。"},{id:"cs-2542",module:"changshi",prompt:"劳动合同的类型不包括？",options:["口头劳动合同", "固定期限劳动合同", "无固定期限劳动合同", "以完成一定工作任务为期限的劳动合同"],answer:0,explanation:"劳动合同的类型包括固定期限、无固定期限、以完成一定工作任务为期限的劳动合同；口头劳动合同不是法定类型。"},{id:"cs-2543",module:"changshi",prompt:"用人单位自用工之日起多久内必须与劳动者订立书面劳动合同？",options:["1个月内", "3个月内", "6个月内", "1年内"],answer:0,explanation:"用人单位自用工之日起1个月内必须与劳动者订立书面劳动合同。"},{id:"cs-2544",module:"changshi",prompt:"用人单位自用工之日起超过1个月不满1年未与劳动者订立书面劳动合同的，应当？",options:["向劳动者每月支付二倍的工资", "向劳动者每月支付三倍的工资", "向劳动者支付补偿金", "解除劳动合同"],answer:0,explanation:"用人单位自用工之日起超过1个月不满1年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。"},{id:"cs-2545",module:"changshi",prompt:"用人单位自用工之日起满1年不与劳动者订立书面劳动合同的，视为？",options:["已订立无固定期限劳动合同", "已订立固定期限劳动合同", "劳动关系不存在", "劳动关系自动解除"],answer:0,explanation:"用人单位自用工之日起满1年不与劳动者订立书面劳动合同的，视为已订立无固定期限劳动合同。"},{id:"cs-2546",module:"changshi",prompt:"劳动合同的必备条款不包括？",options:["试用期", "用人单位的名称、住所和法定代表人或者主要负责人", "劳动者的姓名、住址和居民身份证或者其他有效身份证件号码", "劳动合同期限"],answer:0,explanation:"劳动合同的必备条款包括用人单位信息、劳动者信息、劳动合同期限、工作内容和工作地点、工作时间和休息休假、劳动报酬、社会保险、劳动保护等；试用期是约定条款。"},{id:"cs-2547",module:"changshi",prompt:"试用期最长不得超过？",options:["6个月", "3个月", "1年", "2个月"],answer:0,explanation:"劳动合同期限3个月以上不满1年的，试用期不得超过1个月；1年以上不满3年的，试用期不得超过2个月；3年以上固定期限和无固定期限的，试用期不得超过6个月。"},{id:"cs-2548",module:"changshi",prompt:"同一用人单位与同一劳动者只能约定几次试用期？",options:["1次", "2次", "3次", "不限"],answer:0,explanation:"同一用人单位与同一劳动者只能约定一次试用期。"},{id:"cs-2549",module:"changshi",prompt:"劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的？",options:["80%", "70%", "60%", "90%"],answer:0,explanation:"劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的80%，并不得低于用人单位所在地的最低工资标准。"},{id:"cs-2550",module:"changshi",prompt:"劳动者提前多久通知用人单位可以解除劳动合同？",options:["30日（试用期3日）", "15日", "7日", "60日"],answer:0,explanation:"劳动者提前30日以书面形式通知用人单位（试用期内提前3日通知），可以解除劳动合同。"},{id:"cs-2551",module:"changshi",prompt:"用人单位可以解除劳动合同的情形不包括？",options:["劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作", "劳动者在试用期间被证明不符合录用条件的", "劳动者严重违反用人单位的规章制度", "劳动者严重失职，营私舞弊，给用人单位造成重大损害"],answer:0,explanation:"劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的，用人单位提前30日书面通知或者额外支付劳动者一个月工资后，可以解除劳动合同。"},{id:"cs-2552",module:"changshi",prompt:"用人单位不得解除劳动合同的情形不包括？",options:["劳动者严重违反用人单位的规章制度", "从事接触职业病危害作业的劳动者未进行离岗前职业健康检查", "在本单位患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的", "女职工在孕期、产期、哺乳期的"],answer:0,explanation:"劳动者严重违反用人单位的规章制度的，用人单位可以解除劳动合同。"},{id:"cs-2553",module:"changshi",prompt:"经济补偿金的计算标准是？",options:["每满1年支付1个月工资的标准向劳动者支付", "每满1年支付2个月工资的标准向劳动者支付", "每满1年支付3个月工资的标准向劳动者支付", "每满1年支付半个月工资的标准向劳动者支付"],answer:0,explanation:"经济补偿金按劳动者在本单位工作的年限，每满1年支付1个月工资的标准向劳动者支付。"},{id:"cs-2554",module:"changshi",prompt:"经济补偿金的月工资上限为？",options:["用人单位所在直辖市、设区的市级人民政府公布的本地区上年度职工月平均工资3倍", "用人单位所在地上年度职工月平均工资2倍", "用人单位所在地上年度职工月平均工资5倍", "没有上限"],answer:0,explanation:"劳动者月工资高于用人单位所在直辖市、设区的市级人民政府公布的本地区上年度职工月平均工资3倍的，按职工月平均工资3倍的数额支付，年限最高不超过12年。"},{id:"cs-2555",module:"changshi",prompt:"劳动争议的解决途径不包括？",options:["仲裁", "协商", "调解", "信访"],answer:3,explanation:"劳动争议的解决途径包括协商、调解、仲裁、诉讼；信访不是法定解决途径。"},{id:"cs-2556",module:"changshi",prompt:"劳动争议仲裁的申请期限为？",options:["知道或者应当知道其权利被侵害之日起1年内", "6个月内", "2年内", "3年内"],answer:0,explanation:"劳动争议申请仲裁的时效期间为1年，自当事人知道或者应当知道其权利被侵害之日起计算。"},{id:"cs-2557",module:"changshi",prompt:"劳动争议仲裁的审理期限为？",options:["受理仲裁申请之日起45日内", "30日内", "60日内", "90日内"],answer:0,explanation:"劳动争议仲裁委员会应当自受理仲裁申请之日起45日内结束；案情复杂需要延期的，经批准可以延期并书面通知当事人，但延长期限不得超过15日。"},{id:"cs-2558",module:"changshi",prompt:"劳动争议仲裁的终局裁决适用于？",options:["追索劳动报酬、工伤医疗费、经济补偿或者赔偿金，不超过当地月最低工资标准12个月金额的争议", "所有劳动争议", "仅涉及人身自由的劳动争议", "仅涉及财产权的劳动争议"],answer:0,explanation:"劳动争议仲裁的终局裁决适用于追索劳动报酬、工伤医疗费、经济补偿或者赔偿金，不超过当地月最低工资标准12个月金额的争议。"},{id:"cs-2559",module:"changshi",prompt:"社会保险的种类不包括？",options:["商业保险", "养老保险", "医疗保险", "失业保险"],answer:0,explanation:"社会保险的种类包括养老保险、医疗保险、失业保险、工伤保险、生育保险；商业保险是独立的保险类型。"},{id:"cs-2560",module:"changshi",prompt:"工伤保险的缴费由谁承担？",options:["用人单位", "劳动者", "用人单位和劳动者共同", "国家"],answer:0,explanation:"工伤保险费由用人单位缴纳，劳动者不缴纳。"},{id:"cs-2561",module:"changshi",prompt:"生育保险的缴费由谁承担？",options:["用人单位", "劳动者", "用人单位和劳动者共同", "国家"],answer:0,explanation:"生育保险费由用人单位缴纳，劳动者不缴纳。"},{id:"cs-2562",module:"changshi",prompt:"失业保险的缴费由谁承担？",options:["用人单位和劳动者共同", "仅用人单位", "仅劳动者", "国家"],answer:0,explanation:"失业保险费由用人单位和劳动者共同缴纳。"},{id:"cs-2563",module:"changshi",prompt:"养老保险的缴费由谁承担？",options:["用人单位和劳动者共同", "仅用人单位", "仅劳动者", "国家"],answer:0,explanation:"养老保险费由用人单位和劳动者共同缴纳。"},{id:"cs-2564",module:"changshi",prompt:"医疗保险的缴费由谁承担？",options:["用人单位和劳动者共同", "仅用人单位", "仅劳动者", "国家"],answer:0,explanation:"医疗保险费由用人单位和劳动者共同缴纳。"},{id:"cs-2565",module:"changshi",prompt:"女职工的产假不少于？",options:["98天", "90天", "128天", "158天"],answer:0,explanation:"女职工生育享受98天产假，其中产前可以休假15天。"},{id:"cs-2566",module:"changshi",prompt:"禁止用人单位招用未满多少周岁的未成年人？",options:["16周岁", "14周岁", "18周岁", "20周岁"],answer:0,explanation:"禁止用人单位招用未满16周岁的未成年人。"},{id:"cs-2567",module:"changshi",prompt:"劳动者每日工作时间不超过？",options:["8小时", "6小时", "10小时", "12小时"],answer:0,explanation:"劳动者每日工作时间不超过8小时，每周工作时间不超过44小时。"},{id:"cs-2568",module:"changshi",prompt:"用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过？",options:["1小时", "2小时", "3小时", "4小时"],answer:0,explanation:"用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过1小时。"},{id:"cs-2569",module:"changshi",prompt:"用人单位由于特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过？",options:["3小时", "1小时", "2小时", "4小时"],answer:0,explanation:"用人单位由于特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过3小时，每月不得超过36小时。"},{id:"cs-2570",module:"changshi",prompt:"反垄断法禁止的垄断行为不包括？",options:["正常的市场竞争", "垄断协议", "滥用市场支配地位", "经营者集中"],answer:0,explanation:"反垄断法禁止的垄断行为包括垄断协议、滥用市场支配地位、经营者集中；正常的市场竞争不禁止。"},{id:"cs-2571",module:"changshi",prompt:"垄断协议的类型不包括？",options:["纵向垄断协议中的正常经销", "横向垄断协议", "纵向垄断协议", "轴辐协议"],answer:0,explanation:"垄断协议的类型包括横向垄断协议、纵向垄断协议、轴辐协议；正常经销不是垄断协议。"},{id:"cs-2572",module:"changshi",prompt:"横向垄断协议的典型形式不包括？",options:["转售价格维持", "固定价格", "限制产量", "划分市场"],answer:0,explanation:"横向垄断协议的典型形式包括固定价格、限制产量、划分市场等；转售价格维持属于纵向垄断协议。"},{id:"cs-2573",module:"changshi",prompt:"纵向垄断协议的典型形式是？",options:["转售价格维持", "固定价格", "限制产量", "划分市场"],answer:0,explanation:"纵向垄断协议的典型形式是转售价格维持（固定转售价格、限定最低转售价格）。"},{id:"cs-2574",module:"changshi",prompt:"市场支配地位的认定因素不包括？",options:["市场份额", "控制价格的能力", "财力和技术条件", "企业规模"],answer:3,explanation:"市场支配地位的认定因素包括市场份额、控制价格的能力、财力和技术条件等；企业规模本身不是认定因素。"},{id:"cs-2575",module:"changshi",prompt:"经营者集中的申报标准不包括？",options:["所有经营者集中都必须申报", "参与集中的所有经营者上一会计年度全球营业额合计超过一定数额", "参与集中的所有经营者上一会计年度中国境内营业额合计超过一定数额", "至少两个经营者上一会计年度中国境内营业额均超过一定数额"],answer:0,explanation:"经营者集中达到国务院规定的申报标准的，应当事先申报；不是所有经营者集中都必须申报。"},{id:"cs-2576",module:"changshi",prompt:"反不正当竞争法禁止的行为不包括？",options:["正常降价促销", "混淆行为", "商业贿赂", "虚假宣传"],answer:0,explanation:"反不正当竞争法禁止的行为包括混淆行为、商业贿赂、虚假宣传、侵犯商业秘密等；正常降价促销不禁止。"},{id:"cs-2577",module:"changshi",prompt:"商业秘密的构成要件不包括？",options:["已申请专利", "不为公众所知悉", "具有商业价值", "权利人采取保密措施"],answer:0,explanation:"商业秘密的构成要件是不为公众所知悉、具有商业价值、权利人采取保密措施；已申请专利的技术方案不再是商业秘密。"},{id:"cs-2578",module:"changshi",prompt:"消费者权益保护法的适用范围不包括？",options:["经营者之间的交易", "消费者为生活消费需要购买、使用商品或者接受服务", "农民购买、使用直接用于农业生产的生产资料", "经营者向消费者提供商品或服务"],answer:0,explanation:"消费者权益保护法适用于消费者为生活消费需要购买、使用商品或者接受服务；经营者之间的交易不适用。"},{id:"cs-2579",module:"changshi",prompt:"消费者的权利不包括？",options:["无限退货权", "安全保障权", "知情权", "自主选择权"],answer:0,explanation:"消费者的权利包括安全保障权、知情权、自主选择权、公平交易权、求偿权、结社权、获得知识权、人格尊严权、监督权；无限退货权不是法定权利。"},{id:"cs-2580",module:"changshi",prompt:"经营者不得以格式条款、通知、声明、店堂告示等方式作出排除或者限制消费者权利的规定，其效力是？",options:["无效", "有效", "效力待定", "可撤销"],answer:0,explanation:"经营者不得以格式条款、通知、声明、店堂告示等方式作出排除或者限制消费者权利、减轻或者免除经营者责任、加重消费者责任的规定，其内容无效。"},{id:"cs-2581",module:"changshi",prompt:"产品质量法的产品范围不包括？",options:["建设工程", "工业产品", "日用消费品", "建筑材料"],answer:0,explanation:"产品质量法的产品范围是经过加工、制作，用于销售的产品；建设工程不适用。"},{id:"cs-2582",module:"changshi",prompt:"产品质量责任的归责原则是？",options:["生产者承担无过错责任，销售者承担过错责任", "生产者和销售者都承担无过错责任", "生产者和销售者都承担过错责任", "生产者承担过错责任，销售者承担无过错责任"],answer:0,explanation:"产品质量责任的归责原则是生产者承担无过错责任，销售者承担过错责任。"},{id:"cs-2583",module:"changshi",prompt:"食品安全法的适用范围不包括？",options:["食用农产品的市场销售", "食品生产和加工", "食品经营", "餐饮服务"],answer:0,explanation:"食品安全法的适用范围包括食品生产和加工、食品经营、餐饮服务；食用农产品的市场销售适用该法关于农产品的规定。"},{id:"cs-2584",module:"changshi",prompt:"食品安全标准的性质是？",options:["强制性标准", "推荐性标准", "行业标准", "企业标准"],answer:0,explanation:"食品安全标准是强制执行的标准。"},{id:"cs-2585",module:"changshi",prompt:"电子商务法的适用范围不包括？",options:["线下实体店销售", "电子商务经营者", "电子商务平台经营者", "平台内经营者"],answer:0,explanation:"电子商务法适用于电子商务经营者、电子商务平台经营者、平台内经营者；线下实体店销售不适用。"},{id:"cs-2586",module:"changshi",prompt:"电子商务经营者的义务不包括？",options:["无条件退款", "依法办理市场主体登记", "依法纳税", "保障消费者权益"],answer:0,explanation:"电子商务经营者的义务包括依法办理市场主体登记、依法纳税、保障消费者权益等；无条件退款不是法定义务。"},{id:"cs-2587",module:"changshi",prompt:"广告法的基本准则不包括？",options:["真实性", "合法性", "科学性", "艺术性"],answer:3,explanation:"广告法的基本准则是真实性、合法性、科学性；艺术性不是基本准则。"},{id:"cs-2588",module:"changshi",prompt:"广告不得含有的情形不包括？",options:["使用国家级、最高级、最佳等用语", "妨碍社会公共秩序", "危害人身、财产安全", "使用虚构、伪造的数据"],answer:0,explanation:"广告不得使用国家级、最高级、最佳等用语；使用虚构、伪造的数据也是禁止情形。"},{id:"cs-2589",module:"changshi",prompt:"汇票的当事人不包括？",options:["出票人", "付款人", "收款人", "承兑人"],answer:3,explanation:"汇票的基本当事人包括出票人、付款人、收款人；承兑人是付款人承兑后的身份。"},{id:"cs-2590",module:"changshi",prompt:"票据权利的种类不包括？",options:["追索权", "付款请求权", "抗辩权", "利益偿还请求权"],answer:2,explanation:"票据权利包括付款请求权和追索权；抗辩权是票据债务人的权利。"},{id:"cs-2591",module:"changshi",prompt:"票据权利的时效（汇票持票人对出票人和承兑人的权利）为？",options:["自票据到期日起2年", "自票据到期日起1年", "自票据到期日起6个月", "自票据到期日起3年"],answer:0,explanation:"汇票持票人对出票人和承兑人的权利，自票据到期日起2年。"},{id:"cs-2592",module:"changshi",prompt:"保险法的基本原则不包括？",options:["最大诚信原则", "保险利益原则", "损失补偿原则", "等价有偿原则"],answer:3,explanation:"保险法的基本原则包括最大诚信原则、保险利益原则、损失补偿原则、近因原则；等价有偿是民法原则。"},{id:"cs-2593",module:"changshi",prompt:"保险利益原则的含义是？",options:["投保人对保险标的应当具有法律上承认的利益", "投保人必须是被保险人", "保险人必须承担全部损失", "保险合同必须公证"],answer:0,explanation:"保险利益原则要求投保人对保险标的应当具有法律上承认的利益。"},{id:"cs-2594",module:"changshi",prompt:"保险合同的解除权（投保人）为？",options:["投保人可以随时解除保险合同（货物运输保险合同和运输工具航程保险合同除外）", "投保人不得解除保险合同", "投保人只能在保险事故发生后解除保险合同", "投保人只能在保险期限届满后解除保险合同"],answer:0,explanation:"投保人可以随时解除保险合同，但货物运输保险合同和运输工具航程保险合同除外。"},{id:"cs-2595",module:"changshi",prompt:"银行法的基本原则不包括？",options:["安全性原则", "流动性原则", "效益性原则", "垄断性原则"],answer:3,explanation:"银行法的基本原则包括安全性原则、流动性原则、效益性原则；垄断性原则不是银行法的基本原则。"},{id:"cs-2596",module:"changshi",prompt:"商业银行的设立须经？",options:["国务院银行业监督管理机构批准", "国务院批准", "中国人民银行批准", "省级政府批准"],answer:0,explanation:"商业银行的设立须经国务院银行业监督管理机构批准。"});
