(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-2598",module:"changshi",prompt:"民事诉讼的基本原则不包括？",options:["无罪推定原则", "当事人诉讼权利平等原则", "辩论原则", "处分原则"],answer:0,explanation:"民事诉讼法的基本原则包括当事人诉讼权利平等原则、辩论原则、处分原则等；无罪推定是刑事诉讼法原则。"},{id:"cs-2599",module:"changshi",prompt:"民事诉讼的级别管辖是指？",options:["各级法院之间受理第一审民事案件的分工和权限", "不同地区法院之间的分工", "专门法院之间的分工", "法院内部的分工"],answer:0,explanation:"级别管辖是指各级法院之间受理第一审民事案件的分工和权限。"},{id:"cs-2600",module:"changshi",prompt:"民事诉讼的地域管辖的一般原则是？",options:["原告就被告", "被告就原告", "专属管辖", "协议管辖"],answer:0,explanation:"民事诉讼的地域管辖一般原则是原告就被告，即由被告住所地法院管辖。"},{id:"cs-2601",module:"changshi",prompt:"下列案件中适用专属管辖的是？",options:["因不动产纠纷提起的诉讼", "合同纠纷", "侵权纠纷", "婚姻纠纷"],answer:0,explanation:"因不动产纠纷提起的诉讼由不动产所在地法院专属管辖。"},{id:"cs-2602",module:"changshi",prompt:"协议管辖的条件不包括？",options:["必须书面协议", "与争议有实际联系的地点", "不得违反级别管辖和专属管辖", "必须口头协议"],answer:3,explanation:"协议管辖应当采用书面形式，不得违反级别管辖和专属管辖的规定。"},{id:"cs-2603",module:"changshi",prompt:"移送管辖的条件不包括？",options:["法院已经受理案件", "受理的法院对该案无管辖权", "受移送的法院对该案有管辖权", "受移送的法院不得再移送"],answer:3,explanation:"移送管辖的条件是法院已经受理案件、受理的法院对该案无管辖权、受移送的法院对该案有管辖权；受移送的法院认为无管辖权的应当报请指定管辖，不得再自行移送。"},{id:"cs-2604",module:"changshi",prompt:"指定管辖的适用情形不包括？",options:["当事人协议管辖", "有管辖权的法院由于特殊原因不能行使管辖权", "管辖权发生争议，协商不成", "移送管辖后受移送法院认为无管辖权"],answer:0,explanation:"指定管辖的适用情形包括有管辖权的法院由于特殊原因不能行使管辖权、管辖权发生争议协商不成、移送管辖后受移送法院认为无管辖权；当事人协议管辖不属于指定管辖。"},{id:"cs-2605",module:"changshi",prompt:"民事诉讼当事人包括？",options:["原告、被告、第三人", "仅原告和被告", "仅原告", "仅被告"],answer:0,explanation:"民事诉讼当事人包括原告、被告、第三人。"},{id:"cs-2606",module:"changshi",prompt:"第三人的种类不包括？",options:["有独立请求权的第三人", "无独立请求权的第三人", "共同诉讼人", "辅助第三人"],answer:2,explanation:"第三人分为有独立请求权的第三人和无独立请求权的第三人；共同诉讼人是独立的当事人类型。"},{id:"cs-2607",module:"changshi",prompt:"共同诉讼的种类不包括？",options:["普通共同诉讼", "必要共同诉讼", "代表人诉讼", "集团诉讼"],answer:3,explanation:"共同诉讼的种类包括必要共同诉讼和普通共同诉讼；代表人诉讼是独立的诉讼形式；集团诉讼不是我国民事诉讼法的概念。"},{id:"cs-2608",module:"changshi",prompt:"代表人诉讼的代表人人数为？",options:["2至5人", "1至3人", "3至7人", "5至10人"],answer:0,explanation:"代表人诉讼的代表人人数为2至5人。"},{id:"cs-2609",module:"changshi",prompt:"诉讼代理人的种类不包括？",options:["法定代理人", "委托代理人", "指定代理人", "特别代理人"],answer:3,explanation:"诉讼代理人的种类包括法定代理人、委托代理人、指定代理人；特别代理人不是法定种类。"},{id:"cs-2610",module:"changshi",prompt:"委托代理人的范围不包括？",options:["无民事行为能力人", "律师", "当事人的近亲属", "社会团体推荐的人"],answer:0,explanation:"委托代理人的范围包括律师、当事人的近亲属、社会团体推荐的人等；无民事行为能力人不能作为委托代理人。"},{id:"cs-2611",module:"changshi",prompt:"证据的法定种类中，证明力最强的一般是？",options:["公文书证", "私文书证", "证人证言", "当事人陈述"],answer:0,explanation:"公文书证的证明力一般强于私文书证。"},{id:"cs-2612",module:"changshi",prompt:"举证责任的分配原则是？",options:["谁主张，谁举证", "谁被告，谁举证", "谁原告，谁举证", "谁法院，谁举证"],answer:0,explanation:"举证责任的分配原则是谁主张，谁举证，即当事人对自己提出的主张有责任提供证据。"},{id:"cs-2613",module:"changshi",prompt:"举证责任倒置的情形不包括？",options:["一般合同纠纷", "高度危险作业致人损害", "环境污染致人损害", "饲养动物致人损害"],answer:0,explanation:"举证责任倒置的情形包括高度危险作业致人损害、环境污染致人损害、饲养动物致人损害等；一般合同纠纷不适用举证责任倒置。"},{id:"cs-2614",module:"changshi",prompt:"证据保全的条件不包括？",options:["证据可能灭失", "证据以后难以取得", "当事人申请", "法院主动采取"],answer:3,explanation:"证据保全的条件是证据可能灭失、证据以后难以取得、当事人申请；法院不能主动采取证据保全措施。"},{id:"cs-2615",module:"changshi",prompt:"财产保全的种类不包括？",options:["诉前保全", "诉中保全", "执行保全", "先予执行"],answer:3,explanation:"财产保全的种类包括诉前保全和诉中保全；先予执行是独立的制度。"},{id:"cs-2616",module:"changshi",prompt:"先予执行的适用范围不包括？",options:["所有民事案件", "追索赡养费、扶养费、抚育费、抚恤金、医疗费用的", "追索劳动报酬的", "因情况紧急需要先予执行的"],answer:0,explanation:"先予执行的适用范围包括追索赡养费、扶养费、抚育费、抚恤金、医疗费用的，追索劳动报酬的，因情况紧急需要先予执行的；不是所有民事案件都适用。"},{id:"cs-2617",module:"changshi",prompt:"开庭审理的阶段不包括？",options:["判决阶段", "法庭调查", "法庭辩论", "最后陈述"],answer:0,explanation:"开庭审理的阶段包括法庭调查、法庭辩论、最后陈述等；判决阶段是审理后的阶段。"},{id:"cs-2618",module:"changshi",prompt:"简易程序的适用条件不包括？",options:["事实清楚", "权利义务关系明确", "争议不大", "必须双方同意"],answer:3,explanation:"简易程序的适用条件是事实清楚、权利义务关系明确、争议不大；不要求必须双方同意。"},{id:"cs-2619",module:"changshi",prompt:"简易程序的审理期限为？",options:["3个月", "6个月", "1年", "9个月"],answer:0,explanation:"简易程序的审理期限为3个月。"},{id:"cs-2620",module:"changshi",prompt:"普通程序的审理期限为？",options:["6个月", "3个月", "1年", "9个月"],answer:0,explanation:"普通程序的审理期限为6个月，特殊情况可以延长。"},{id:"cs-2621",module:"changshi",prompt:"上诉的期限（判决）为？",options:["15日", "10日", "30日", "6个月"],answer:0,explanation:"当事人不服地方人民法院第一审判决的，有权在判决书送达之日起15日内向上一级人民法院提起上诉。"},{id:"cs-2622",module:"changshi",prompt:"上诉的期限（裁定）为？",options:["10日", "15日", "30日", "6个月"],answer:0,explanation:"当事人不服地方人民法院第一审裁定的，有权在裁定书送达之日起10日内向上一级人民法院提起上诉。"},{id:"cs-2623",module:"changshi",prompt:"二审的审理期限（判决）为？",options:["3个月", "6个月", "1年", "9个月"],answer:0,explanation:"二审法院应当在立案之日起3个月内审结。"},{id:"cs-2624",module:"changshi",prompt:"执行程序的申请期限为？",options:["2年", "1年", "3年", "6个月"],answer:0,explanation:"申请执行的期间为2年，自法律文书规定履行期间的最后一日起计算。"},{id:"cs-2625",module:"changshi",prompt:"执行措施的种类不包括？",options:["限制出境", "查询、冻结、划拨被执行人的存款", "查封、扣押、拍卖、变卖被执行人的财产", "对被执行人判处刑罚"],answer:3,explanation:"执行措施包括查询、冻结、划拨被执行人的存款，查封、扣押、拍卖、变卖被执行人的财产，限制出境等；对被执行人判处刑罚是刑事处罚，不是执行措施。"},{id:"cs-2626",module:"changshi",prompt:"公示催告程序的适用范围是？",options:["可以背书转让的票据被盗、遗失或者灭失", "所有民事案件", "仅合同纠纷", "仅侵权纠纷"],answer:0,explanation:"公示催告程序适用于可以背书转让的票据被盗、遗失或者灭失的案件。"},{id:"cs-2627",module:"changshi",prompt:"督促程序的适用条件是？",options:["债权人请求债务人给付金钱、有价证券", "所有民事案件", "仅合同纠纷", "仅侵权纠纷"],answer:0,explanation:"督促程序适用于债权人请求债务人给付金钱、有价证券的案件。"},{id:"cs-2628",module:"changshi",prompt:"特别程序的适用范围不包括？",options:["选民资格案件", "宣告失踪、宣告死亡案件", "认定公民无民事行为能力、限制民事行为能力案件", "合同纠纷案件"],answer:3,explanation:"特别程序的适用范围包括选民资格案件、宣告失踪宣告死亡案件、认定公民无民事行为能力限制民事行为能力案件等；合同纠纷案件适用普通程序或简易程序。"},{id:"cs-2629",module:"changshi",prompt:"民事诉讼中，调解的原则不包括？",options:["自愿原则", "合法原则", "事实清楚原则", "查明事实、分清是非原则"],answer:2,explanation:"民事诉讼中调解的原则包括自愿原则、合法原则、查明事实分清是非原则；事实清楚原则不是调解原则。"},{id:"cs-2630",module:"changshi",prompt:"刑事诉讼的基本原则不包括？",options:["无罪推定原则", "侦查权、检察权、审判权由专门机关依法行使", "严格遵守法定程序", "审判公开"],answer:0,explanation:"刑事诉讼的基本原则包括侦查权检察权审判权由专门机关依法行使、严格遵守法定程序、审判公开等；无罪推定不是我国刑事诉讼法的基本原则。"},{id:"cs-2631",module:"changshi",prompt:"刑事诉讼中的专门机关不包括？",options:["司法行政机关", "公安机关", "人民检察院", "人民法院"],answer:0,explanation:"刑事诉讼中的专门机关包括公安机关、人民检察院、人民法院、国家安全机关、军队保卫部门、监狱等；司法行政机关不是刑事诉讼的专门机关。"},{id:"cs-2632",module:"changshi",prompt:"刑事案件的侦查由谁进行？",options:["公安机关", "人民检察院", "人民法院", "司法行政机关"],answer:0,explanation:"刑事案件的侦查由公安机关进行，法律另有规定的除外。"},{id:"cs-2633",module:"changshi",prompt:"贪污贿赂犯罪由谁侦查？",options:["国家监察委员会", "公安机关", "人民检察院", "人民法院"],answer:0,explanation:"贪污贿赂犯罪由国家监察委员会调查。"},{id:"cs-2634",module:"changshi",prompt:"司法工作人员的职务犯罪由谁侦查？",options:["人民检察院", "公安机关", "人民法院", "监察委员会"],answer:0,explanation:"司法工作人员利用职权实施的非法拘禁、刑讯逼供、非法搜查等侵犯公民权利、损害司法公正的犯罪，由人民检察院立案侦查。"},{id:"cs-2635",module:"changshi",prompt:"刑事强制措施的种类不包括？",options:["训诫", "拘传", "取保候审", "监视居住"],answer:0,explanation:"刑事强制措施包括拘传、取保候审、监视居住、拘留、逮捕；训诫不是强制措施。"},{id:"cs-2636",module:"changshi",prompt:"辩护人的种类不包括？",options:["侦查人员", "律师", "人民团体推荐的人", "犯罪嫌疑人、被告人的监护人、亲友"],answer:0,explanation:"辩护人的种类包括律师、人民团体推荐的人、犯罪嫌疑人被告人的监护人亲友等；侦查人员不能担任辩护人。"},{id:"cs-2637",module:"changshi",prompt:"辩护人的责任不包括？",options:["为犯罪嫌疑人、被告人定罪量刑提出意见", "根据事实和法律，提出犯罪嫌疑人、被告人无罪、罪轻或者减轻、免除其刑事责任的材料和意见", "维护犯罪嫌疑人、被告人的诉讼权利和其他合法权益", "维护犯罪嫌疑人、被告人的合法权益"],answer:0,explanation:"辩护人的责任是根据事实和法律，提出犯罪嫌疑人、被告人无罪、罪轻或者减轻、免除其刑事责任的材料和意见，维护其诉讼权利和其他合法权益；为定罪量刑提出意见不是辩护人的责任。"},{id:"cs-2638",module:"changshi",prompt:"法律援助的适用对象不包括？",options:["所有犯罪嫌疑人", "经济困难的犯罪嫌疑人", "盲、聋、哑的犯罪嫌疑人", "尚未完全丧失辨认或者控制自己行为能力的精神病人"],answer:0,explanation:"法律援助的适用对象包括经济困难的犯罪嫌疑人、盲聋哑的犯罪嫌疑人、尚未完全丧失辨认或者控制自己行为能力的精神病人等；不是所有犯罪嫌疑人都适用。"},{id:"cs-2639",module:"changshi",prompt:"刑事证据的种类不包括？",options:["推理", "物证", "书证", "证人证言"],answer:0,explanation:"刑事证据的种类包括物证、书证、证人证言、被害人陈述、犯罪嫌疑人被告人供述和辩解、鉴定意见、勘验检查笔录、视听资料、电子数据；推理不是证据种类。"},{id:"cs-2640",module:"changshi",prompt:"证据确实充分的条件不包括？",options:["定罪量刑的事实都有证据证明", "据以定案的证据均经法定程序查证属实", "综合全案证据，对所认定事实已排除合理怀疑", "证据必须经过公证"],answer:3,explanation:"证据确实充分的条件是定罪量刑的事实都有证据证明、据以定案的证据均经法定程序查证属实、综合全案证据对所认定事实已排除合理怀疑；证据不需要经过公证。"},{id:"cs-2641",module:"changshi",prompt:"非法证据排除规则适用于？",options:["采用刑讯逼供等非法方法收集的犯罪嫌疑人、被告人供述和采用暴力、威胁等非法方法收集的证人证言、被害人陈述", "所有证据", "仅书证", "仅物证"],answer:0,explanation:"非法证据排除规则适用于采用刑讯逼供等非法方法收集的犯罪嫌疑人、被告人供述和采用暴力、威胁等非法方法收集的证人证言、被害人陈述。"},{id:"cs-2642",module:"changshi",prompt:"侦查措施的种类不包括？",options:["讯问犯罪嫌疑人", "询问证人", "搜查", "判决"],answer:3,explanation:"侦查措施包括讯问犯罪嫌疑人、询问证人、搜查、扣押物证书证、鉴定、通缉等；判决是审判阶段的措施。"},{id:"cs-2643",module:"changshi",prompt:"不起诉的种类不包括？",options:["缓起诉", "法定不起诉", "酌定不起诉", "存疑不起诉"],answer:0,explanation:"不起诉的种类包括法定不起诉、酌定不起诉、存疑不起诉、附条件不起诉；缓起诉不是不起诉的种类。"},{id:"cs-2644",module:"changshi",prompt:"审判组织的种类不包括？",options:["合议庭", "独任庭", "审判委员会", "陪审团"],answer:3,explanation:"审判组织的种类包括合议庭、独任庭、审判委员会；陪审团不是我国审判组织的种类。"},{id:"cs-2645",module:"changshi",prompt:"合议庭的组成人数为？",options:["3人以上单数", "2人以上", "5人以上", "7人以上"],answer:0,explanation:"合议庭的组成人数为3人以上单数。"},{id:"cs-2646",module:"changshi",prompt:"公开审判的例外不包括？",options:["涉及商业秘密的案件", "涉及国家秘密的案件", "涉及个人隐私的案件", "未成年人犯罪案件"],answer:0,explanation:"公开审判的例外包括涉及国家秘密的案件、涉及个人隐私的案件、未成年人犯罪案件；涉及商业秘密的案件可以申请不公开审理，但不是法定例外。"},{id:"cs-2647",module:"changshi",prompt:"第一审程序的审理期限为？",options:["2个月，至迟不超过3个月", "1个月", "6个月", "1年"],answer:0,explanation:"第一审程序的审理期限为2个月，至迟不超过3个月。"},{id:"cs-2648",module:"changshi",prompt:"二审的审理方式不包括？",options:["书面审理", "开庭审理", "调查讯问式审理", "缺席审理"],answer:3,explanation:"二审的审理方式包括开庭审理、调查讯问式审理、书面审理；缺席审理不是二审的审理方式。"},{id:"cs-2649",module:"changshi",prompt:"死刑复核程序的核准机关是？",options:["最高人民法院", "高级人民法院", "中级人民法院", "最高人民检察院"],answer:0,explanation:"死刑由最高人民法院核准。"},{id:"cs-2650",module:"changshi",prompt:"审判监督程序的启动主体不包括？",options:["当事人", "各级人民法院院长", "最高人民法院", "最高人民检察院"],answer:0,explanation:"审判监督程序的启动主体包括各级人民法院院长、最高人民法院、最高人民检察院等；当事人可以申请再审，但不能直接启动审判监督程序。"},{id:"cs-2651",module:"changshi",prompt:"执行程序的种类不包括？",options:["死刑执行", "有期徒刑执行", "拘役执行", "缓刑执行"],answer:3,explanation:"执行程序包括死刑执行、有期徒刑执行、拘役执行、管制执行等；缓刑执行是缓刑考验期，不是执行程序。"},{id:"cs-2652",module:"changshi",prompt:"社区矫正的适用对象不包括？",options:["被判处死刑的罪犯", "被判处管制的罪犯", "被宣告缓刑的罪犯", "被裁定假释的罪犯"],answer:0,explanation:"社区矫正的适用对象包括被判处管制的罪犯、被宣告缓刑的罪犯、被裁定假释的罪犯、被决定暂予监外执行的罪犯；被判处死刑的罪犯不适用社区矫正。"},{id:"cs-2653",module:"changshi",prompt:"仲裁的基本原则不包括？",options:["一裁终局原则", "自愿原则", "依据事实和法律原则", "公开审理原则"],answer:3,explanation:"仲裁的基本原则包括自愿原则、依据事实和法律原则、独立仲裁原则、一裁终局原则；仲裁一般不公开审理。"},{id:"cs-2654",module:"changshi",prompt:"仲裁的适用范围不包括？",options:["婚姻、收养、监护、扶养、继承纠纷", "合同纠纷", "财产权益纠纷", "其他财产权益纠纷"],answer:0,explanation:"仲裁的适用范围是平等主体的公民、法人和其他组织之间发生的合同纠纷和其他财产权益纠纷；婚姻、收养、监护、扶养、继承纠纷不适用仲裁。"},{id:"cs-2655",module:"changshi",prompt:"仲裁协议的形式不包括？",options:["口头协议", "仲裁条款", "仲裁协议书", "其他书面形式"],answer:0,explanation:"仲裁协议应当采用书面形式，包括合同中的仲裁条款、仲裁协议书和其他书面形式；口头协议不是仲裁协议的形式。"},{id:"cs-2656",module:"changshi",prompt:"仲裁协议的内容不包括？",options:["仲裁庭的组成方式", "请求仲裁的意思表示", "仲裁事项", "选定的仲裁委员会"],answer:0,explanation:"仲裁协议的内容包括请求仲裁的意思表示、仲裁事项、选定的仲裁委员会；仲裁庭的组成方式不是仲裁协议的必备内容。"},{id:"cs-2657",module:"changshi",prompt:"仲裁协议的效力不包括？",options:["排除法院管辖权", "约束当事人", "约束仲裁委员会", "约束第三人"],answer:3,explanation:"仲裁协议的效力包括排除法院管辖权、约束当事人、约束仲裁委员会；不约束第三人。"},{id:"cs-2658",module:"changshi",prompt:"仲裁庭的组成方式不包括？",options:["由法院指定仲裁员", "由3名仲裁员组成", "由1名仲裁员组成", "由当事人约定"],answer:0,explanation:"仲裁庭可以由3名仲裁员或者1名仲裁员组成，由当事人约定；仲裁员由当事人选定或约定，不由法院指定。"},{id:"cs-2659",module:"changshi",prompt:"仲裁员的回避情形不包括？",options:["与本案有利害关系", "是本案当事人或者当事人、代理人的近亲属", "与本案当事人、代理人有其他关系，可能影响公正仲裁的", "与本案当事人是同一国籍"],answer:3,explanation:"仲裁员的回避情形包括与本案有利害关系、是本案当事人或者当事人代理人的近亲属、与本案当事人代理人有其他关系可能影响公正仲裁的等；与本案当事人是同一国籍不是回避情形。"},{id:"cs-2660",module:"changshi",prompt:"仲裁的审理方式一般为？",options:["不公开审理", "公开审理", "书面审理", "缺席审理"],answer:0,explanation:"仲裁一般不公开审理，当事人协议公开的可以公开，但涉及国家秘密的除外。"},{id:"cs-2661",module:"changshi",prompt:"仲裁裁决的撤销事由不包括？",options:["裁决的事项不属于仲裁协议的范围或者仲裁委员会无权仲裁的", "没有仲裁协议的", "裁决所根据的证据是伪造的", "当事人对裁决结果不满意"],answer:3,explanation:"仲裁裁决的撤销事由包括没有仲裁协议的、裁决的事项不属于仲裁协议的范围或者仲裁委员会无权仲裁的、裁决所根据的证据是伪造的等；当事人对裁决结果不满意不是撤销事由。"},{id:"cs-2662",module:"changshi",prompt:"仲裁裁决的执行机关是？",options:["人民法院", "仲裁委员会", "公安机关", "检察机关"],answer:0,explanation:"仲裁裁决由人民法院执行。"},{id:"cs-2663",module:"changshi",prompt:"仲裁裁决的不予执行事由不包括？",options:["裁决的事项不属于仲裁协议的范围或者仲裁委员会无权仲裁的", "没有仲裁协议的", "认定事实的主要证据不足的", "当事人对裁决结果不满意"],answer:3,explanation:"仲裁裁决的不予执行事由包括没有仲裁协议的、裁决的事项不属于仲裁协议的范围或者仲裁委员会无权仲裁的、认定事实的主要证据不足的等；当事人对裁决结果不满意不是不予执行事由。"},{id:"cs-2664",module:"changshi",prompt:"涉外仲裁的适用法律不包括？",options:["当事人选择的法律", "仲裁地法律", "与争议有最密切联系的法律", "仲裁员国籍国法律"],answer:3,explanation:"涉外仲裁的适用法律包括当事人选择的法律、仲裁地法律、与争议有最密切联系的法律；仲裁员国籍国法律不是适用法律。"},{id:"cs-2665",module:"changshi",prompt:"仲裁裁决的承认与执行（涉外）依据是？",options:["《纽约公约》", "《海牙公约》", "《维也纳公约》", "《巴黎公约》"],answer:0,explanation:"涉外仲裁裁决的承认与执行依据是《承认及执行外国仲裁裁决公约》（《纽约公约》）。"},{id:"cs-2666",module:"changshi",prompt:"仲裁与诉讼的区别不包括？",options:["仲裁公开，诉讼不公开", "仲裁一裁终局，诉讼两审终审", "仲裁自愿，诉讼强制", "仲裁专业，诉讼一般"],answer:0,explanation:"仲裁一般不公开审理，诉讼一般公开审理；仲裁与诉讼的区别不包括仲裁公开诉讼不公开。"},{id:"cs-2667",module:"changshi",prompt:"仲裁与调解的区别不包括？",options:["仲裁有强制执行力，调解没有", "仲裁由第三方裁决，调解由第三方促成和解", "仲裁一裁终局，调解可以反悔", "仲裁和调解没有区别"],answer:3,explanation:"仲裁与调解的区别包括仲裁有强制执行力调解没有、仲裁由第三方裁决调解由第三方促成和解、仲裁一裁终局调解可以反悔；仲裁和调解有区别。"},{id:"cs-2668",module:"changshi",prompt:"仲裁与行政裁决的区别不包括？",options:["仲裁由民间机构进行，行政裁决由行政机关进行", "仲裁自愿，行政裁决强制", "仲裁专业，行政裁决一般", "仲裁和行政裁决没有区别"],answer:3,explanation:"仲裁与行政裁决的区别包括仲裁由民间机构进行行政裁决由行政机关进行、仲裁自愿行政裁决强制、仲裁专业行政裁决一般；仲裁和行政裁决有区别。"},{id:"cs-2669",module:"changshi",prompt:"仲裁与和解的区别不包括？",options:["仲裁有第三方参与，和解没有", "仲裁有强制执行力，和解没有", "仲裁专业，和解一般", "仲裁与和解没有区别"],answer:3,explanation:"仲裁与和解的区别包括仲裁有第三方参与和解没有、仲裁有强制执行力和解没有、仲裁专业和解一般；仲裁与和解有区别。"},{id:"cs-2670",module:"changshi",prompt:"仲裁协议的无效情形不包括？",options:["约定的仲裁事项超出法律规定的仲裁范围的", "无民事行为能力人或者限制民事行为能力人订立的仲裁协议", "一方采取胁迫手段订立的仲裁协议", "当事人对仲裁委员会的选择不满意"],answer:3,explanation:"仲裁协议的无效情形包括约定的仲裁事项超出法律规定的仲裁范围的、无民事行为能力人或者限制民事行为能力人订立的仲裁协议、一方采取胁迫手段订立的仲裁协议等；当事人对仲裁委员会的选择不满意不是无效情形。"},{id:"cs-2671",module:"changshi",prompt:"仲裁协议的独立性是指？",options:["仲裁协议独立存在，合同的变更、解除、终止或者无效不影响仲裁协议的效力", "仲裁协议依附于合同", "仲裁协议随合同变更而变更", "仲裁协议随合同终止而终止"],answer:0,explanation:"仲裁协议的独立性是指仲裁协议独立存在，合同的变更、解除、终止或者无效不影响仲裁协议的效力。"},{id:"cs-2672",module:"changshi",prompt:"仲裁庭的组成人数为？",options:["3人或1人", "5人", "7人", "9人"],answer:0,explanation:"仲裁庭可以由3名仲裁员或者1名仲裁员组成。"},{id:"cs-2673",module:"changshi",prompt:"仲裁庭的组成（3人仲裁庭）为？",options:["双方当事人各选定1名仲裁员，共同选定或由仲裁委员会主任指定第3名仲裁员（首席仲裁员）", "由仲裁委员会主任指定全部仲裁员", "由法院指定全部仲裁员", "由当事人共同选定全部仲裁员"],answer:0,explanation:"3人仲裁庭由双方当事人各选定1名仲裁员，共同选定或者由仲裁委员会主任指定第3名仲裁员（首席仲裁员）。"},{id:"cs-2674",module:"changshi",prompt:"仲裁庭的组成（1人仲裁庭）为？",options:["由双方当事人共同选定或者共同委托仲裁委员会主任指定", "由仲裁委员会主任指定", "由法院指定", "由一方当事人指定"],answer:0,explanation:"1人仲裁庭由双方当事人共同选定或者共同委托仲裁委员会主任指定。"},{id:"cs-2675",module:"changshi",prompt:"仲裁庭的开庭地点为？",options:["仲裁委员会所在地或者当事人约定的地点", "必须在仲裁委员会所在地", "必须在当事人所在地", "必须在法院"],answer:0,explanation:"仲裁庭的开庭地点为仲裁委员会所在地或者当事人约定的地点。"},{id:"cs-2676",module:"changshi",prompt:"仲裁庭的裁决方式为？",options:["按照多数仲裁员的意见作出，少数仲裁员的不同意见可以记入笔录", "按照首席仲裁员的意见作出", "按照少数仲裁员的意见作出", "按照仲裁委员会主任的意见作出"],answer:0,explanation:"仲裁庭的裁决按照多数仲裁员的意见作出，少数仲裁员的不同意见可以记入笔录。"},{id:"cs-2677",module:"changshi",prompt:"仲裁庭不能形成多数意见时，裁决按照谁的意见作出？",options:["首席仲裁员的意见", "少数仲裁员的意见", "仲裁委员会主任的意见", "法院的意见"],answer:0,explanation:"仲裁庭不能形成多数意见时，裁决按照首席仲裁员的意见作出。"},{id:"cs-2678",module:"changshi",prompt:"仲裁裁决书的生效时间是？",options:["裁决书自作出之日起发生法律效力", "裁决书送达之日起生效", "裁决书签收之日起生效", "裁决书公证之日起生效"],answer:0,explanation:"裁决书自作出之日起发生法律效力。"});
